const DEMO=window.STUDIODECK_DEMO===true;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:Number(c)%100?2:0}).format(Number(c)/100);
const bytes=n=>n>1024*1024?(n/1024/1024).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
const date=s=>s?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(s)):'';
const initials=s=>String(s||'Studio').split(/[ @]+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join('');
const cats={moodboard:'Moodboards',renders:'Images & renders',drawings:'Drawings & details',budget:'Budgets & quotes',presentation:'Design presentations',other:'Other files'};
const icons={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',folder:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z',slide:'M3 3h18v13H3zM12 16v5M7 21h10',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',left:'M14 6l-6 6 6 6',right:'M10 6l6 6-6 6',down:'M6 9l6 6 6-6',up:'M12 19V5M5 12l7-7 7 7',upload:'M12 16V3M7 8l5-5 5 5M4 16v4h16v-4',download:'M12 3v13M7 11l5 5 5-5M4 17v4h16v-4',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'M5 12l4 4L19 6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 2',chat:'M21 11a8 8 0 0 1-8 8H6l-4 3V9a8 8 0 0 1 8-8h3a8 8 0 0 1 8 8z',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3zM20 1v4M18 3h4',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0zM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',mail:'M3 4h18v16H3zM3 5l9 8 9-8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75',close:'M6 6l12 12M6 18L18 6',more:'M5 12h.01M12 12h.01M19 12h.01',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',play:'M8 5l11 7-11 7z',history:'M3 11a9 9 0 1 1 2 7M3 3v8h8M12 7v5l4 2',image:'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M9 7h.01',budget:'M3 4h18v16H3zM3 9h18M8 9v11M16 13h2M16 17h2',activity:'M2 12h5l3-9 4 18 3-9h5',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',help:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M9 8a3 3 0 1 1 5 3c-2 1-2 2-2 3M12 18h.01',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',copy:'M8 8h13v13H8zM16 8V3H3v13h5',edit:'M16 3l5 5M3 21l5-1L21 7a2 2 0 0 0-5-5L3 15z',warning:'M12 3L1 21h22zM12 9v5M12 17h.01',phone:'M7 3H3v4c0 8 6 14 14 14h4v-5l-5-2-2 3a14 14 0 0 1-7-7l3-2z',expand:'M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5',minus:'M5 12h14',menu:'M3 6h18M3 12h18M3 18h18',leaf:'M20 3C5 2 2 10 6 16s15 3 14-13zM4 21l11-11',send:'M22 2L9 15M22 2l-7 20-6-7-7-6z',logout:'M9 3H3v18h6M9 12h12M16 7l5 5-5 5'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const button=(label,act,kind='',extra='',ico='')=>`<button type="button" class="button ${kind}" data-action="${act}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const iconBtn=(n,act,title,extra='')=>`<button type="button" class="icon-button" data-action="${act}" aria-label="${esc(title)}" title="${esc(title)}" ${extra}>${icon(n)}</button>`;
const brand=()=>'<span class="brand">studio<span>deck</span><i>®</i></span>';
const state={user:null,csrf:null,data:null,projects:[],tab:'overview',present:false,client:false,shareToken:'',slide:0,imageIndex:0,filter:'all',search:'',openCosts:new Set(),zoom:1,poll:null,chat:[],busy:false};
const imageCache=new Map();let activeModal=null,previousFocus=null;
const getActions=new Set(['session','projects','project','deck','document_page','file','studio_users']);
async function api(action,body={}){
  if(DEMO)return demoRequest(action,body);
  const get=getActions.has(action),params=new URLSearchParams({action});if(get)for(const [k,v]of Object.entries(body))if(v!=null)params.set(k,v);
  const headers={};if(state.shareToken)headers.Authorization='Bearer '+state.shareToken;if(state.csrf&&!get)headers['X-CSRF-Token']=state.csrf;
  const opts={method:get?'GET':'POST',credentials:'same-origin',headers};if(!get){if(body instanceof FormData)opts.body=body;else{headers['Content-Type']='application/json';opts.body=JSON.stringify(body);}}
  const response=await fetch('api.php?'+params,opts);let result;try{result=await response.json();}catch{throw Error('The studio server is unavailable. Please check that the PHP application is running.');}if(!response.ok)throw Error(result.error||'This request could not be completed.');return result;
}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),6500);}
const pending=()=>state.data?.jobs?.some(j=>['queued','running'].includes(j.status));
const editable=()=>!state.client&&state.data?.can_edit!==false&&state.data?.iteration.status==='draft';
const theme=()=>{let t=state.data?.project.theme||{};if(typeof t==='string')try{t=JSON.parse(t);}catch{t={};}return {style:t.style||'Your design direction',font:t.font||'serif',colors:(t.colors?.length?t.colors:['#e8e3d7','#b99f7d','#756b59','#626f55','#3c4134']).filter(x=>/^#[a-f0-9]{6}$/i.test(x))};};
const photoFiles=(category='renders')=>visualSlides(state.data||{files:[]}).filter(s=>s.type===({renders:'render',photos:'photo',drawings:'drawing'}[category]||category)).map(s=>s.visual);
function imageUrl(f){if(!f)return '';return (!f.slide_image_version&&!f.page_number&&f.preview_url)||imageCache.get(imageKey(f))||((!f.slide_image_version&&!f.page_number&&f.url&&f.mime?.startsWith('image/'))?f.url:'');}
function img(f,alt='',extra=''){const url=imageUrl(f);return url?`<img src="${esc(url)}" alt="${esc(alt||f.name)}" loading="lazy" ${extra}>`:`<div class="image-pending" data-image="${esc(imageKey(f))}" data-version="${esc(f.id)}" data-slide="${esc(f.slide_id||'')}" data-variant="${esc(f.slide_image_version||'')}" data-original="${f.show_original?'1':''}" data-page="${f.page_number||''}" data-crop="${f.image_number||''}" data-alt="${esc(alt||f.name)}" ${extra}>${icon('image')}</div>`;}
const hydratingImages=new Set();
async function hydrateImages(){if(DEMO)return;const d=state.data;if(!d)return;
    for(const placeholder of document.querySelectorAll('[data-image]')){
        const key=placeholder.dataset.image;if(hydratingImages.has(key))continue;
        const p=new URLSearchParams({action:placeholder.dataset.slide&&!placeholder.dataset.slide.startsWith('legacy-')?'slide_image':placeholder.dataset.page?'document_page':'file',id:placeholder.dataset.version,iteration:d.iteration.id,preview:1});
        if(placeholder.dataset.slide)p.set('slide_id',placeholder.dataset.slide);if(placeholder.dataset.original==='1')p.set('original','1');
        if(placeholder.dataset.page)p.set('page',placeholder.dataset.page);if(placeholder.dataset.crop)p.set('image',placeholder.dataset.crop);
        hydratingImages.add(key);
        try{let url=imageCache.get(key);if(!url){const r=await fetch('api.php?'+p,{credentials:'same-origin',headers:state.shareToken?{Authorization:'Bearer '+state.shareToken}:{}});if(!r.ok)continue;url=URL.createObjectURL(await r.blob());const decoded=new Image();decoded.src=url;await decoded.decode();imageCache.set(key,url);}
            document.querySelectorAll(`[data-image="${CSS.escape(key)}"]`).forEach(el=>{const im=document.createElement('img');im.src=url;im.alt=el.dataset.alt;im.loading='lazy';im.className=el.className.replace('image-pending','');im.style.cssText=el.style.cssText;el.replaceWith(im);});
        }catch{}finally{hydratingImages.delete(key);}
    }
}
async function prepareGeneratedImages(previous,updated){
    const old=new Map((previous?.slides||[]).map(s=>[s.id,s.image_version_id]));
    for(const slide of updated.slides||[]){
        if(!slide.image_version_id||old.get(slide.id)===slide.image_version_id)continue;
        for(const original of [false,true]){
            const f={id:slide.source_version_id,page_number:slide.page_number,image_number:slide.image_number,slide_image_version:original?'':slide.image_version_id,show_original:original},key=imageKey(f);
            if(imageCache.has(key)||DEMO)continue;
            const params=new URLSearchParams({action:'slide_image',iteration:updated.iteration.id,slide_id:slide.id});if(original)params.set('original','1');
            try{const response=await fetch('api.php?'+params,{credentials:'same-origin',headers:state.shareToken?{Authorization:'Bearer '+state.shareToken}:{}});if(!response.ok)continue;const url=URL.createObjectURL(await response.blob()),im=new Image();im.src=url;await im.decode();imageCache.set(key,url);}catch{}
        }
    }
}
async function openProject(pid,iid=null){state.present=false;state.inspectHidden=false;state.client=false;state.shareToken='';state.data=await api('project',{id:pid,iteration:iid});state.slide=0;state.imageIndex=0;state.chat=[];render();pollJobs();}
async function refresh(){if(!state.data)return;const scroll=window.scrollY;const previous=JSON.stringify(state.data),updated=await api(state.client?'deck':'project',state.client?{}:{id:state.data.project.id,iteration:state.data.iteration.id});await prepareGeneratedImages(state.data,updated);state.data=updated;if(JSON.stringify(updated)!==previous){render();renderProcessing();if(magnifiedPhoto)renderPhotoLightbox();}window.scrollTo(0,scroll);pollJobs();}
function pollJobs(){clearTimeout(state.poll);if(state.tab==='projects'&&!state.present){if(state.projects.some(p=>p.processing))state.poll=setTimeout(async()=>{try{await loadProjects();const grid=$('#project-grid');if(grid)grid.innerHTML=projectTiles();}catch(error){toast(error.message);}pollJobs();},2200);return;}if(pending())state.poll=setTimeout(()=>refresh().catch(e=>{toast(e.message);pollJobs();}),1800);}
function slideDefs(){return presentationSlides(state.data,{includeHidden:!!state.inspectHidden});}
function slideFiles(id){if(id==='summary'||id==='intro')return state.data.files;if(id==='changes')return state.data.files.filter(f=>f.number>1);const def=slideDefs().find(s=>s.id===id);if(def?.visual)return state.data.files.filter(f=>f.id===def.visual.id);return state.data.files.filter(f=>f.category===id);}
function render(){applyStudioTheme(studioPreview||state.studioTheme,!state.present&&!state.client&&!!state.user);if(!state.present){state.inspectHidden=false;document.documentElement.style.removeProperty('--green');document.documentElement.style.removeProperty('--heading');document.documentElement.style.removeProperty('--deck-bg');}if(!state.user&&!state.client){renderLogin();return;}if(state.present){renderPresentation();return;}renderWorkspace();hydrateImages();}
function sidebar(){return `<aside class="sidebar"><button data-action="projects" aria-label="Your projects">${brand()}</button><div class="studio-switch"><span class="studio-mark">${esc(initials(state.studio?.name||'Studio'))}</span><select id="studio-select" aria-label="Current studio">${(state.studios||[{id:'demo',name:'Your design studio'}]).map(s=>`<option value="${esc(s.id)}" ${s.id===state.studio?.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>${iconBtn('plus','new-studio','Create a studio')}</div><p class="sidebar-caption">WORKSPACE</p><button class="side-link ${state.tab==='projects'?'active':''}" data-action="projects">${icon('grid')}All projects</button><button class="side-link ${state.tab!=='projects'?'active':''}" data-action="tab" data-tab="overview">${icon('folder')}Current project</button><button class="side-link" data-action="tab" data-tab="activity">${icon('activity')}Activity</button><button class="side-link ${state.tab==='studio-users'?'active':''}" data-action="studio-users">${icon('users')}Studio users</button><div class="sidebar-bottom"><button class="side-link" data-action="settings">${icon('settings')}Studio settings</button><button class="side-link" data-action="help">${icon('help')}A little guidance</button><div class="profile"><span class="avatar">${esc(initials(state.user?.name))}</span><div>${esc(state.user?.name||'Your studio')}<small>Interior designer</small></div><button data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside>`;}
function renderWorkspace(){const d=state.data,p=d?.project,tab=state.tab;$('#app').innerHTML=`<div class="workspace">${sidebar()}<div class="workspace-body"><header class="topbar"><div class="row">${iconBtn('menu','menu','Open navigation')}<div class="breadcrumbs"><button data-action="projects">Projects</button>${p&&tab!=='projects'?`${icon('right')}<span>${esc(p.name)}</span>`:''}</div></div><div class="row">${DEMO?'<button class="demo-indicator" data-action="demo-info">Interactive demo '+icon('help')+'</button>':`<span class="muted">Your private studio</span>`}</div></header><main class="main-content" id="main">${tab==='studio-users'?studioUsersPage():tab==='projects'?projectList():d?projectPage():empty('Your next project starts here','Create a project, add your clients, and drop in your design files.','new-project','Create a project')}</main></div></div>`;const m=$('[data-action="menu"]');if(m)m.classList.add('mobile-menu');}
function empty(title,description,action='',label=''){return `<div class="empty">${icon('folder')}<h2>${esc(title)}</h2><p>${esc(description)}</p>${action?button(esc(label),action,'primary','','plus'):''}</div>`;}
function projectTiles(){const search=(state.projectSearch||'').trim().toLowerCase(),projects=state.projects.filter(p=>[p.name,p.location,p.description].join(' ').toLowerCase().includes(search));return projects.length?projects.map(p=>`<article class="project-tile"><button class="project-tile-open" data-action="open-project" data-id="${esc(p.id)}"><div class="project-art">${icon(p.archived?'history':'folder')}</div><div><div class="row between"><h2>${esc(p.name)}</h2>${p.pinned?`<span title="Pinned">${icon('pin')}</span>`:''}</div><p>${esc(p.location||'New project')} · ${p.file_count||0} files</p><div class="row wrap"><span class="tag">${p.visibility==='public'?'Public in studio':'Team members only'}</span>${p.archived?'<span class="tag">Archived</span>':''}${p.processing?'<span class="project-processing" role="status"><span class="loading-inline"></span>Processing files</span>':''}</div></div></button><div class="project-tile-actions">${button(p.pinned?'Unpin':'Pin','pin-project','small ghost',`data-id="${esc(p.id)}" data-pinned="${p.pinned?'0':'1'}"`,'pin')}${p.can_edit?button(p.archived?'Restore':'Archive','archive-project','small ghost',`data-id="${esc(p.id)}" data-archived="${p.archived?'0':'1'}"`,'history'):''}</div></article>`).join(''):empty(search?'No matching projects':'No projects to show',search?'Try another name or location.':'Create a project or turn on Show archived.');}
function projectList(){return `<div class="project-head"><div><h1>Your projects</h1><p class="project-sub">${esc(state.studio?.name||'Your studio')} · Your teams and public studio projects.</p></div>${button('New project','new-project','primary','','plus')}</div><div class="project-filters"><label class="project-search">${icon('search')}<input id="project-search" type="search" placeholder="Search projects…" aria-label="Search projects" value="${esc(state.projectSearch||'')}"></label><label class="check-label"><input id="show-archived" type="checkbox" ${state.showArchived?'checked':''}>Show archived</label></div><div class="project-grid" id="project-grid">${projectTiles()}</div>`;}
async function loadProjects(){state.projects=(await api('projects',{archived:state.showArchived?1:0})).projects;}

function projectPage(){const d=state.data,p=d.project,i=d.iteration;const tabs=[['overview','Overview'],['slides','Presentation'],['files','Files'],['budget','Budget'],['activity','Activity']];return `<div class="project-head"><div><h1>${esc(p.name)}</h1><div class="project-sub">${icon('pin')}<span>${esc(p.location||'Interior design project')}</span><span class="sep"></span><span>Residential interior</span><span class="tag ${i.status==='draft'?'':'green'}">${i.status==='draft'?'In progress':'Shared with clients'}</span></div></div><div class="row">${state.data.can_edit!==false?button('Project settings','project-settings','','','settings'):''}${editable()?button('Project style','theme','','','edit'):''}${button('Preview','preview','','','eye')}${state.data.can_edit!==false?button('Send to clients','share','primary','','send'):''}</div></div><div class="tabs-row"><nav class="tabs" aria-label="Project sections">${tabs.map(([key,title])=>`<button class="tab ${key===state.tab?'active':''}" data-action="tab" data-tab="${key}">${title}${key==='files'?`<small>${d.files.length}</small>`:''}${key==='activity'&&d.comments.length?`<small>${d.comments.length}</small>`:''}</button>`).join('')}</nav><select class="iteration-select" aria-label="Select project iteration" id="iteration-select">${(d.iterations||[i]).map(x=>`<option value="${esc(x.id)}" ${x.id===i.id?'selected':''}>Iteration ${String(x.number).padStart(2,'0')} · ${esc(x.status)}</option>`).join('')}</select></div>${processingBanner()}${d.jobs?.some(j=>j.status==='failed')?`<div class="notice">Some files need attention. ${button('Review processing','job-status','small')}</div>`:''}${state.tab==='overview'?overview():state.tab==='slides'?allSlides():state.tab==='files'?filePage():state.tab==='budget'?budgetPage():activityPage()}`;}
function overview(){const d=state.data,i=d.iteration;const hero=photoFiles()[0]||photoFiles('photos')[0]||photoFiles('moodboard')[0];const ready=d.files.length>0&&!pending();const clients=d.contacts.filter(x=>x.role==='Client');return `<div class="overview-grid"><div><div class="cover-card">${hero?img(hero,'Interior design concept'):''}<span class="cover-badge">CONCEPT ${String(i.number).padStart(2,'0')} · ${esc(theme().style.toUpperCase())}</span><button class="icon-button cover-dots" data-action="iteration" aria-label="Manage iterations">${icon('more')}</button><div class="cover-caption"><div><p class="eyebrow">${esc(d.project.location||'YOUR NEXT CHAPTER')}</p><h2>A place to<br>come home to.</h2></div><button class="round-play" data-action="preview" aria-label="Preview the client presentation">${icon('play')}</button></div></div><div class="cover-meta"><span>${icon('slide')}${slideDefs().length} slides<span>·</span>${d.files.length} source files</span><span>${icon('clock')}${esc(i.title)}</span></div><div class="section-title"><h2>Your presentation</h2><button class="text-button" data-action="tab" data-tab="slides">View all slides ${icon('arrow')}</button></div><div class="slide-cards">${slideDefs().filter(s=>s.visual||s.id==='budget').slice(0,4).map(s=>slideThumb(s.id)).join('')}</div></div><div class="overview-right"><div class="review-panel"><div class="row between"><h2 class="panel-heading">${i.status==='shared'?'Out in the world':'A little check before sharing'}</h2></div><div class="review-steps">${[[true,'Project created','A home for your ideas'],[d.files.length>0,'Files added',d.files.length+' originals, kept safely'],[ready,'Presentation assembled',ready?'Ready for your review':pending()?'Processing files — slides appear when finished':'Add files to get started'],[i.status==='shared','Shared with your clients',i.status==='shared'?'This iteration is preserved':'Your preview comes first']].map(([done,title,sub])=>`<div class="review-step"><span class="step-check ${done?'done':''}">${done?icon('check'):''}</span><div>${title}<small>${sub}</small></div></div>`).join('')}</div>${button('Preview presentation','preview','primary wide','','play')}<p>See it exactly as your clients will.</p><div class="client-mini"><span class="avatar">${esc(initials(clients[0]?.name||'Client'))}</span><span>${clients.length?esc(clients[0].name):'Add your clients'}${clients.length>1?' +'+(clients.length-1):''}</span><button data-action="contacts" aria-label="View project contacts">${icon('users')}</button></div></div><div class="recent-note"><div class="row between"><h3>Recently in this project</h3><button class="text-button" data-action="tab" data-tab="activity" aria-label="View all activity">${icon('arrow')}</button></div>${d.events.slice(0,2).map(e=>`<div class="mini-event">${icon(e.type==='change_requested'?'chat':'history')}<div>${esc(e.detail)}<small>${esc(date(e.created_at))}</small></div></div>`).join('')||'<p class="muted">Your project activity will appear here.</p>'}</div></div></div><div class="upload-theme-row">${dropzone()}${themeCard()}</div><div class="below-label">${icon('lock')}Your originals are always preserved. Every change has a history.</div>`;}
function dropzone(){return `<div class="dropzone" data-dropzone tabindex="0" role="button" aria-label="Upload project files"><div class="drop-icon">${icon('upload')}</div><div><h3>${editable()?'Drop your files here, or <span>browse</span>':'Ready for the next chapter?'}</h3><p>${editable()?'PowerPoint, Excel, PDF & images · Up to 30 MB per file':'Create an iteration to add or replace files.'}</p></div><input type="file" id="upload-input" hidden multiple accept=".pdf,.ppt,.pptx,.xls,.xlsx,.csv,.jpg,.jpeg,.png,.webp"></div>`;}
function themeCard(){const t=theme();return `<div class="theme-card"><div class="row between"><h3>Your project’s look & feel</h3><button data-action="theme" aria-label="Edit project styling">${icon('edit')}</button></div><div class="swatches">${t.colors.map(c=>`<span class="swatch" style="background:${c}" title="${c}"></span>`).join('')}</div><div class="row">${icon('spark')}<span>${esc(t.style)}</span><span>·</span><span>${t.font==='serif'?'Editorial serif':'Modern sans'}</span></div></div>`;}
function slideThumb(id){const defs=slideDefs(),idx=defs.findIndex(x=>x.id===id),def=defs[idx];if(!def)return '';const f=def.visual||(id==='intro'?(photoFiles()[0]||photoFiles('photos')[0]):null);return `<button class="slide-thumb" data-action="go-slide" data-slide="${idx}"><div class="thumb-art">${f?img(f):id==='budget'?`<div class="mini-budget"><strong>${money(state.data.total_cents)}</strong><div class="mini-bars"><i></i><i></i><i></i></div></div>`:icon(def.icon)}${def.record?`<span class="tag">${esc(visualTypes[def.type])}${def.situation!=='unknown'?' · '+esc({before:'Before',concept:'Concept',after:'After',reference:'Reference'}[def.situation]):''}</span>`:''}</div><div class="thumb-title"><small>${String(idx+1).padStart(2,'0')}</small><span>${esc(def.title)}</span></div></button>`;}
const slideTypeName=s=>visualTypes[s.type]||({intro:'Introduction',source:'Document page',changes:'Changes',budget:'Budget',contacts:'Contacts',summary:'Summary'}[s.type])||'Image';
function editorSlides(){return presentationSlides(state.data,{includeHidden:true});}
function openEditorSlide(id,zoom=false){const def=editorSlides().find(s=>s.id===id);if(!def)return;state.inspectHidden=def.hidden;startPresentation(slideDefs().findIndex(s=>s.id===id));if(zoom)openPhotoLightbox();}
function allSlides(){
    const defs=editorSlides(),visible=defs.filter(s=>!s.hidden).length,list=state.slideView!=='grid';
    return `<div class="section-title slide-editor-heading"><div><h2>Your client’s journey</h2><p class="muted">${visible} visible · ${defs.length-visible} hidden. Drag slides to reorder, or use the arrow buttons.</p></div><div class="row wrap">${button('List','slide-view',list?'small active':'small',`data-view="list"`,'menu')}${button('Grid','slide-view',!list?'small active':'small',`data-view="grid"`,'grid')}${button('New iteration','iteration','small','','plus')}${button('Preview all','preview','small','','play')}</div></div>${!editable()?'<p class="notice">This shared iteration is preserved. Create a new iteration to edit the slides.</p>':''}${pending()?'<p class="notice">Your files are still being processed. New slides will appear here automatically when each file finishes.</p>':''}<div class="slide-editor ${list?'slide-editor-list':'all-slides'}">${defs.map((s,n)=>{
        const f=s.visual,origin=f?`${f.source_name||f.name}${f.page_number?' · Page '+f.page_number:''}${f.image_number?' · Image '+f.image_number:''}`:'Project information';
        const preview=f?img(f,s.title):s.type==='budget'?`<strong>${money(state.data.total_cents)}</strong>`:icon(s.icon);
        return `<article class="slide-editor-row slide-card-item ${s.hidden?'is-hidden':''}" data-slide-id="${esc(s.id)}" draggable="${editable()}"><div class="slide-order"><span title="Drag to reorder" aria-hidden="true">⠿</span><small>${String(n+1).padStart(2,'0')}</small></div><button class="editor-slide-preview" data-action="open-editor-slide" data-id="${esc(s.id)}" aria-label="Preview ${esc(s.title)}">${preview}</button><div class="editor-slide-details"><div class="row wrap"><span class="tag outline">${s.record?'Detected type: ':''}${esc(slideTypeName(s))}</span>${s.hidden?'<span class="tag">Hidden</span>':''}</div><h3>${esc(s.title)}</h3><p>${esc(s.record?.description||situations[s.situation]||'Presentation section')}</p><small class="slide-origin">${esc(origin)}</small></div><div class="editor-slide-actions">${f?button('Zoom in','zoom-editor-slide','small',`data-id="${esc(s.id)}"`,'expand'):''}${editable()?`${s.record&&!s.record.legacy?button('Edit labels','edit-slide','small ghost',`data-id="${esc(s.record.id)}"`,'edit'):''}${button(s.hidden?'Show':'Hide','visibility-slide','small',`data-id="${esc(s.id)}" data-operation="${s.hidden?'show':'hide'}"`,'eye')}${button('Delete','delete-slide','small danger-text',`data-id="${esc(s.id)}"`,'minus')}<div class="row">${iconBtn('up','move-editor-slide','Move slide up',`data-id="${esc(s.id)}" data-direction="-1" ${n===0?'disabled':''}`)}${iconBtn('down','move-editor-slide','Move slide down',`data-id="${esc(s.id)}" data-direction="1" ${n===defs.length-1?'disabled':''}`)}</div>`:''}</div></article>`;
    }).join('')||(pending()?'':'<p class="notice">No slides remain in this presentation. Add a new source file to create slides.</p>')}</div>`;
}
async function changeSlideLayout(operation,extra={}){if(!requireDraft())return;await api('slide_layout',{iteration:state.data.iteration.id,operation,...extra});await refresh();}
async function reorderEditorSlide(id,target){const order=editorSlides().map(s=>s.id),from=order.indexOf(id);if(from<0||target<0||target>=order.length||from===target)return;order.splice(from,1);order.splice(target,0,id);await changeSlideLayout('reorder',{order});document.querySelector(`[data-slide-id="${CSS.escape(id)}"] [data-action="move-editor-slide"]`)?.focus({preventScroll:true});}
let draggedSlide=null;
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-slide-id]');if(!row||!editable())return;draggedSlide=row.dataset.slideId;e.dataTransfer.setData('text/plain',draggedSlide);e.dataTransfer.effectAllowed='move';row.classList.add('dragging');});
document.addEventListener('dragover',e=>{const row=e.target.closest('[data-slide-id]');if(!row||!draggedSlide)return;e.preventDefault();e.stopPropagation();e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));row.classList.add('drop-target');},true);
document.addEventListener('drop',async e=>{const row=e.target.closest('[data-slide-id]');if(!row||!draggedSlide)return;e.preventDefault();e.stopPropagation();const id=draggedSlide;draggedSlide=null;try{await reorderEditorSlide(id,editorSlides().findIndex(s=>s.id===row.dataset.slideId));}catch(error){toast(error.message);}finally{document.querySelectorAll('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging'));}},true);
document.addEventListener('dragend',()=>{draggedSlide=null;document.querySelectorAll('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging'));});
const expandedFiles=new Set();
function extractedAssets(file){
    const stem=file.name.replace(/\.[^.]+$/,'');
    return (file.pages||[]).flatMap(page=>{
        const prefix=`${stem}-page-${String(page.number).padStart(3,'0')}`;
        const assets=[];
        if(page.has_preview)assets.push({page:page.number,image:0,kind:'page',name:prefix+'.jpg',type:'Page preview'});
        for(const im of page.images||[]){const slide=state.data.slides?.find(s=>s.source_version_id===file.id&&s.page_number===page.number&&s.image_number===im.number);assets.push({page:page.number,image:im.number,kind:'image',name:`${prefix}-image-${String(im.number).padStart(3,'0')}.jpg`,size:im.size,slide,type:visualTypes[slide?.type]||'Image to review'});}
        if(page.has_text)assets.push({page:page.number,image:0,kind:'text',name:prefix+'.txt',type:'Extracted text'});
        return assets.map(a=>({...a,id:`${file.id}:${a.page}:${a.kind}:${a.image}`,source:file}));
    });
}
function findExtractedAsset(id){return state.data.files.flatMap(extractedAssets).find(a=>a.id===id);}
function assetImage(a){return {...a.source,name:a.name,page_number:a.page,image_number:a.image,has_preview:true};}
function extractedRows(file,assets){return `<div class="extracted-file-list" role="group" aria-label="Files extracted from ${esc(file.name)}">${assets.map(a=>`<div class="extracted-file-row"><button class="extracted-file-thumb" data-action="preview-extracted" data-id="${esc(a.id)}" aria-label="Preview ${esc(a.name)}">${a.kind==='text'?icon('file'):img(assetImage(a),a.name)}</button><div class="extracted-file-name"><strong>${esc(a.name)}</strong><small>Page ${a.page}${a.image?' · Image '+a.image:''}${a.size?' · '+bytes(a.size):''}${a.slide?.title?' · '+esc(a.slide.title):''}</small></div><div class="extracted-file-classification"><span class="tag outline">${esc(a.type)}</span>${a.slide?`<small>${esc(situations[a.slide.situation])}</small>`:''}</div><div class="file-actions">${a.slide&&editable()?iconBtn('edit','edit-slide','Edit extracted image classification',`data-id="${esc(a.slide.id)}"`):''}${iconBtn('eye','preview-extracted','Preview extracted file',`data-id="${esc(a.id)}"`)}${iconBtn('download','download-extracted','Download extracted file',`data-id="${esc(a.id)}"`)}</div></div>`).join('')}</div>`;}
function explorerFileRow(f){const assets=extractedAssets(f),expanded=expandedFiles.has(f.id);return `<div class="file-group"><div class="file-row"><div class="file-name">${assets.length?`<button class="icon-button extraction-toggle" data-action="toggle-extracted" data-id="${esc(f.id)}" aria-label="${expanded?'Collapse':'Expand'} extracted files for ${esc(f.name)}" aria-expanded="${expanded}">${icon(expanded?'down':'right')}</button>`:`<span class="file-icon">${icon(f.mime.startsWith('image/')?'image':'file')}</span>`}<span><strong>${esc(f.name)}</strong><small>${bytes(f.size)} · Original source${assets.length?' · '+assets.length+' extracted files':''}</small></span></div><select class="file-category" data-category="${esc(f.asset_id)}" aria-label="Category for ${esc(f.name)}" ${editable()?'':'disabled'}>${Object.entries(cats).map(([c,t])=>`<option value="${c}" ${c===f.category?'selected':''}>${t}</option>`).join('')}</select><span class="file-version">v${f.number}</span><div class="file-actions">${/\.(pdf|pptx?)$/i.test(f.name)?iconBtn('eye','review-pages','View extracted pages',`data-id="${esc(f.id)}"`):''}${iconBtn('history','history','Version history',`data-id="${esc(f.id)}"`)}${iconBtn('upload','replace','Replace file',`data-id="${esc(f.id)}"`)}${iconBtn('download','download','Download original',`data-id="${esc(f.id)}"`)}</div></div>${expanded?extractedRows(f,assets):''}</div>`;}
function filePage(){const d=state.data,visible=d.files.filter(f=>(state.filter==='all'||f.category===state.filter)&&f.name.toLowerCase().includes(state.search.toLowerCase()));return `<div class="file-tools"><div class="search">${icon('search')}<input id="file-search" value="${esc(state.search)}" placeholder="Find a project file…" aria-label="Search project files"></div><div class="row">${button('New iteration','iteration','','','plus')}${button('Add files','upload','primary','','upload')}</div></div><div class="filter-chips">${[['all','All files'],...Object.entries(cats)].map(([key,name])=>`<button class="${state.filter===key?'active':''}" data-action="filter" data-filter="${key}">${name}</button>`).join('')}</div>${visible.length?`<p class="file-explorer-hint">Expand a source document to browse its extracted images, page previews and text files.</p><div class="file-table"><div class="file-row header"><span>File name</span><span>Category</span><span>Version</span><span></span></div>${visible.map(explorerFileRow).join('')}</div>`:empty(d.files.length?'No matching files':'Bring your ideas together',d.files.length?'Try another category or file name.':'Drop in a moodboard, a render, a drawing or a quote.')}<div style="margin-top:24px">${dropzone()}</div>${d.files.some(f=>f.metadata?.warnings?.length)?`<details class="file-review"><summary>Files that need a closer look</summary><ul>${d.files.flatMap(f=>(f.metadata?.warnings||[]).map(w=>`<li><strong>${esc(f.name)}:</strong> ${esc(w)}</li>`)).join('')}</ul></details>`:''}`;}
async function previewExtracted(id){const a=findExtractedAsset(id);if(!a)return;let content;if(a.kind==='text'){const page=await api('document_page',{id:a.source.id,iteration:state.data.iteration.id,page:a.page});content=`<pre class="extracted-text">${esc(page.text)}</pre>`;}else content=`<div class="extracted-asset-preview">${img(assetImage(a),a.name)}</div>`;openModal(a.name,`<p>${esc(a.source.name)} · Page ${a.page} · ${esc(a.type)}</p>${content}<div class="modal-footer">${a.slide&&editable()?button('Edit classification','edit-slide','small',`data-id="${esc(a.slide.id)}"`,'edit'):''}${button('Download file','download-extracted','primary',`data-id="${esc(a.id)}"`,'download')}</div>`,true);hydrateImages();}
async function downloadExtracted(id){const a=findExtractedAsset(id);if(!a)return;let blob;if(a.kind==='text'){const p=await api('document_page',{id:a.source.id,iteration:state.data.iteration.id,page:a.page});blob=new Blob([p.text],{type:'text/plain;charset=utf-8'});}else{const params=new URLSearchParams({action:'document_page',id:a.source.id,iteration:state.data.iteration.id,page:a.page,...(a.image?{image:a.image}:{preview:1})});const r=await fetch('api.php?'+params,{credentials:'same-origin',headers:state.shareToken?{Authorization:'Bearer '+state.shareToken}:{}});if(!r.ok)throw Error('This extracted file is unavailable.');blob=await r.blob();}const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),20000);}
function activityPage(){const events=state.data.events||[];return `<div class="section-title"><h2>Every step, in one place</h2><div class="row">${button('Client feedback','feedback','small','','chat')}${button('Manage links','manage-links','small','','link')}</div></div>${events.length?`<div class="timeline">${events.map(e=>`<article class="timeline-item"><span class="event-icon">${icon(e.type==='change_requested'?'chat':e.type.includes('view')?'eye':e.type.includes('sent')?'send':'history')}</span><div><h3>${esc(e.actor)}</h3><p>${esc(e.detail)}</p><small>${esc(e.type.replaceAll('_',' '))} · ${esc(date(e.created_at))}</small></div></article>`).join('')}</div>`:empty('The story starts here','Client views, downloads, shared iterations and feedback will appear here.')}`;}
function budgetRow(item,depth=0){if(depth>8)return '';const children=state.data.budget.filter(x=>x.parent_id===item.id),open=state.openCosts.has(item.id);return `<div class="budget-row"><div class="budget-line"><button class="budget-disclosure" data-action="${children.length?'toggle-cost':'cost'}" data-id="${esc(item.id)}" ${children.length?`aria-expanded="${open}"`:''}>${icon(children.length?(open?'down':'right'):'file')}<div><h3>${esc(item.label)}${Number(item.included)?'<span class="tag green">Included in parent</span>':''}</h3><p>${esc(item.vendor||'Vendor to be confirmed')}${children.length?' · '+children.length+' subquotes':''}${item.kind==='estimate'?' · Estimate':''}</p></div></button><div class="row"><span class="amount">${item.amount_cents===null?'TBC':money(item.amount_cents)}</span><button class="budget-source" data-action="cost" data-id="${esc(item.id)}" aria-label="View details of ${esc(item.label)}">${icon('expand')}</button></div></div>${children.length&&open?`<div class="budget-children">${children.map(x=>budgetRow(x,depth+1)).join('')}</div>`:''}</div>`;}
function budgetPage(){const d=state.data,items=d.budget,roots=items.filter(x=>!x.parent_id&&x.amount_cents!==null),unknown=items.filter(x=>x.amount_cents===null),colors=['#7c8c69','#a7a184','#c4b294','#d9ccad','#b2bfa2','#d6dccb'];return `<div class="budget-layout"><section><div class="budget-top"><div><span class="eyebrow muted">Known project total</span><div class="budget-total">${money(d.total_cents)}</div><p>${unknown.length?`${unknown.length} costs to be specified`:'Based on the recorded budget'} · Iteration ${String(d.iteration.number).padStart(2,'0')}</p></div>${!state.client?button('Add cost','add-cost','small','','plus'):''}</div>${roots.length?`<div class="budget-chart" aria-hidden="true">${roots.map((x,n)=>`<span style="flex:${Math.max(0,Number(x.amount_cents))};background:${colors[n%colors.length]}"></span>`).join('')}</div><div class="row between budget-section-label"><span>Cost breakdown</span><span>Explore each quote</span></div><div class="budget-rows">${roots.map(x=>budgetRow(x)).join('')}</div>`:empty('Your budget starts with a source','Upload a quote or budget workbook, or add a cost yourself.',!state.client?'add-cost':'',!state.client?'Add a cost':'')}${unknown.length?`<div class="unknown-box"><h3>${icon('warning')}Still to be specified <span class="tag amber">${unknown.length}</span></h3><p>Amounts are still to be confirmed. Included subquotes may already be covered by their parent total.</p>${unknown.map(x=>`<button class="unknown-line wide" style="width:100%;text-align:left" data-action="cost" data-id="${esc(x.id)}">${esc(x.label)}<span>${Number(x.included)?'Included · amount TBC':'To be confirmed'} ${icon('right')}</span></button>`).join('')}</div>`:''}<p class="budget-note">Included subquotes are shown within their parent quote and counted once. Estimates can change. Check each source for VAT, exclusions and validity.</p></section>${chatPanel()}</div>`;}
function chatPanel(){return `<aside class="chat-panel"><div class="chat-heading"><h3>${icon('spark')}A little clarity on costs</h3><p>Ask about this project’s budget.</p></div><div class="chat-body" id="chat-messages">${state.chat.length?state.chat.map(m=>`<div class="chat-message ${m.role}">${esc(m.text)}${m.sources?.length?`<div class="sources">${m.sources.map((s,i)=>`<button data-action="download" data-id="${esc(s)}">${icon('file')}Source ${i+1}</button>`).join('')}</div>`:''}</div>`).join(''):`<div class="chat-message muted">Let’s make the numbers feel clear. What would you like to know?</div><div class="chat-chips">${['What is still unspecified?','Are subquotes counted twice?','What is the total budget?'].map(q=>`<button data-action="ask" data-question="${esc(q)}">${q} ${icon('arrow')}</button>`).join('')}</div>`}${state.busy?'<span class="loading-inline" aria-label="Preparing answer"></span>':''}</div><form class="chat-form" data-form="chat"><input name="question" placeholder="Ask about the budget…" aria-label="Ask about the budget" required maxlength="2000"><button aria-label="Send question" ${state.busy?'disabled':''}>${icon('up')}</button></form><p class="chat-footer">${state.data.capabilities.ai?'AI answers · check linked sources':'Budget helper · AI connection not enabled'}</p></aside>`;}
function renderPresentation(){const colors=theme().colors;const rgb=c=>[1,3,5].map(n=>parseInt(c.slice(n,n+2),16));const luma=c=>{const [r,g,b]=rgb(c);return r*.2126+g*.7152+b*.0722;};const dark=[...colors].sort((a,b)=>luma(a)-luma(b))[0];const light=[...colors].sort((a,b)=>luma(b)-luma(a))[0];if(dark&&luma(dark)<130)document.documentElement.style.setProperty('--green',dark);if(light){const tint='#'+rgb(light).map(v=>Math.round(v*.12+255*.88).toString(16).padStart(2,'0')).join('');document.documentElement.style.setProperty('--deck-bg',tint);}const defs=slideDefs();state.slide=Math.max(0,Math.min(state.slide,defs.length-1));if(!defs.length){$('#app').innerHTML=`<div class="empty-state"><h1>No visible slides</h1>${!state.client?button('Back to studio','exit-preview'):''}</div>`;return;}const def=defs[state.slide],d=state.data,t=theme();document.documentElement.style.setProperty('--heading',t.font==='sans'?'Arial,sans-serif':"Georgia,'Times New Roman',serif");$('#app').innerHTML=`<div class="presentation">${previewBar()}<header class="presentation-top">${brand()}<span class="project-label">${esc(d.project.name)} · ${esc(d.project.location)}</span><div class="row"><span class="tag outline">Concept ${String(d.iteration.number).padStart(2,'0')}</span>${button('Leave feedback','feedback','','','chat')}</div></header><main class="slide-area" id="main">${slideContent(def.id)}</main><footer class="presentation-footer"><button class="slide-originals" data-action="originals">${icon('download')}Source files <span class="tag outline">${slideFiles(def.id).length}</span></button><nav class="slide-nav-dots" aria-label="Presentation slides">${defs.map((s,n)=>`<button class="${n===state.slide?'active':''}" data-action="go-slide" data-slide="${n}" aria-label="${n+1}. ${esc(s.title)}" ${n===state.slide?'aria-current="step"':''}></button>`).join('')}</nav><div class="row">${iconBtn('left','prev-slide','Previous slide',state.slide===0?'disabled':'')}<span class="slide-counter">${String(state.slide+1).padStart(2,'0')} / ${String(defs.length).padStart(2,'0')}</span>${iconBtn('right','next-slide','Next slide',state.slide===defs.length-1?'disabled':'')}</div></footer></div>`;hydrateImages();}
function slideContent(id){const d=state.data,t=theme(),def=slideDefs().find(s=>s.id===id);if(def?.visual)return individualVisualSlide(def);if(id==='intro'){const f=photoFiles()[0]||photoFiles('photos')[0]||photoFiles('moodboard')[0];return `<section class="cover-slide"><div><p class="slide-label">A new chapter · Concept ${String(d.iteration.number).padStart(2,'0')}</p><h1 class="slide-heading">A place to<br>come home to.</h1><p class="project-name">${esc(d.project.name)}</p><p class="slide-description">${esc(d.project.description||'An invitation to explore the possibilities for your space.')}</p>${button('Explore your home','next-slide','primary start-presentation','','arrow')}</div><div class="cover-slide-image">${f?img(f,'Your interior design concept'):empty('Your concept, coming together','Add a render or a moodboard to bring this page to life.')}</div></section>`;}
 if(id==='budget')return `<section class="presentation-budget"><p class="slide-label">A clear view of the numbers</p><h1 class="slide-heading">The investment.</h1>${budgetPage()}</section>`;
 if(id==='changes'){const delta=d.previous_total_cents!==null?d.total_cents-d.previous_total_cents:null;return `<p class="slide-label">Making it yours · Iteration ${d.iteration.number}</p><h1 class="slide-heading">A little closer<br>to your kind of home.</h1><div class="changes-grid"><div>${d.changes.length?d.changes.map(c=>`<div class="change-item"><span class="change-mark">${icon(c.type==='added'?'plus':c.type==='removed'?'minus':'check')}</span><span>${esc(c.name)}</span><span class="tag outline">${esc(c.type)}</span></div>`).join(''):'<p class="slide-description">'+(d.iteration.number===1?'This is the first concept. Future iterations will show what has changed here.':'No source files have changed since the previous iteration.')+'</p>'}<p class="budget-note">All unchanged files carry forward. Earlier iterations remain available in your studio.</p></div><aside class="change-card"><h3>Budget movement</h3><strong>${delta===null?'First concept':(delta>0?'+':'')+money(delta)}</strong><p>${delta===null?'Your starting point for the project.':'Compared with the previous iteration’s known costs.'}</p><p>${d.budget.filter(x=>x.amount_cents===null).length} costs remain unspecified.</p></aside></div>`;}
 if(id==='contacts')return `<p class="slide-label">Good design is a conversation</p><div class="row between wrap"><h1 class="slide-heading">Your project team.</h1>${!state.client?button('Add a contact','add-contact','small','','plus'):''}</div><p class="slide-description">A question, an idea, a small change. We’re here.</p><div class="contacts-grid">${d.contacts.filter(c=>c.role!=='Client').map(c=>`<article class="contact-card"><span class="avatar">${esc(initials(c.name))}</span><h3>${esc(c.name)}</h3><p>${esc(c.role)}</p><a href="mailto:${esc(encodeURIComponent(c.email))}">${icon('mail')}${esc(c.email)}</a>${c.phone?`<a href="tel:${esc(c.phone.replace(/[^\d+]/g,''))}">${icon('phone')}${esc(c.phone)}</a>`:''}</article>`).join('')}</div>`;
 return `<p class="slide-label">Your next chapter</p><h1 class="slide-heading">Everything, together.</h1><div class="summary-layout"><div><p class="slide-description">Take a little time to imagine yourself here. Your design, the details and the numbers are all in one place.</p><div class="summary-stats"><div><strong>${money(d.total_cents)}</strong><span>Known investment</span></div><div><strong>${d.files.length}</strong><span>Source files</span></div></div>${button('Share your thoughts','feedback','primary','','chat')}<p class="budget-note">${d.budget.filter(x=>x.amount_cents===null).length} costs remain unspecified. This presentation does not replace the original drawings or vendor quotes.</p></div><div class="download-list"><h3>Yours to keep</h3>${d.files.map(f=>`<button data-action="history" data-id="${esc(f.id)}"><span>${esc(f.name)}<small>${cats[f.category]} · Version ${f.number} · Originals & history</small></span>${icon('download')}</button>`).join('')||'<p class="budget-note">Files will appear here once added.</p>'}</div></div>`;
}
const showOriginalSlides=new Set(),showGeneratedSlides=new Set();
installComparisonControls();
function slideImageJob(id){return latestSlideImageJob(state.data?.jobs,id);}
function imageWorking(job){return job&&['queued','running'].includes(job.status);}
function slideImageStatus(def){
    const job=slideImageJob(def.record?.id);
    if(imageWorking(job))return `<div class="image-working" role="status" aria-live="polite"><span class="image-working-scan" aria-hidden="true"></span><div><span class="loading-inline" aria-hidden="true"></span><strong>${job.status==='queued'?'Waiting to make this render photorealistic':'Making this render photorealistic'}</strong><small>Refining light, textures & shadows. You can keep working.</small></div></div>`;
    return '';
}
function comparisonVisual(def,fullScreen=false){
    const id=def.record.id,f=def.visual,value=comparisonPosition(id),original={...f,show_original:true,slide_image_version:''};
    return `<div class="image-comparison" data-comparison="${esc(id)}" style="--comparison:${value}%">
        <div class="comparison-layer comparison-generated">${img(f,'Generated: '+def.title)}</div>
        <div class="comparison-layer comparison-original">${img(original,'Original: '+def.title)}</div>
        <span class="comparison-label comparison-label-original">Original</span><span class="comparison-label comparison-label-generated">Photorealistic</span>
        <span class="comparison-divider" aria-hidden="true"><span>‹ ⋮ ›</span></span>
        <input type="range" min="0" max="100" value="${value}" data-comparison-range="${esc(id)}" aria-label="Compare original and photorealistic image" aria-valuetext="${value}% original, ${100-value}% generated">
        ${!fullScreen?`<button class="comparison-zoom icon-button" data-action="magnify-photo" aria-label="Zoom in comparison">${icon('expand')}</button>`:''}
    </div>`;
}
function comparingImage(def){return !!def.record?.image_version_id&&!showOriginalSlides.has(def.record.id)&&!showGeneratedSlides.has(def.record.id);}
function visualImageArea(def,f,fullScreen=false){
    const content=comparingImage(def)?comparisonVisual(def,fullScreen):fullScreen?img(f,def.title):`<button class="photo-magnify visual-image-button" data-action="magnify-photo" aria-label="Zoom in: ${esc(def.title)}">${img(f,def.title)}<span class="photo-magnify-hint">${icon('expand')}Zoom in</span></button>`;
    return `<div class="visual-image-area ${fullScreen?'fullscreen-image-area':'single-visual '+(def.type==='render'?'render-visual':'photo-visual')}">${content}${slideImageStatus(def)}</div>`;
}

function individualVisualSlide(def){
    const r=def.record||{},t=theme(),original=showOriginalSlides.has(r.id),f={...def.visual,show_original:original,slide_image_version:original?'':def.visual.slide_image_version};
    const source=state.data.files.find(x=>x.id===f.id),location=f.page_number?` · Page ${f.page_number}${f.image_number?' · Image '+f.image_number:''}`:'';
    const labels=`<span class="tag outline">${def.record?'Detected type: ':''}${esc(visualTypes[def.type]||'Document')}</span>${def.record?`<span class="tag ${def.situation==='before'?'':'outline'}">${esc(situations[def.situation])}</span>`:''}${r.image_version_id?'<span class="tag outline">AI visualization</span>':''}`;
    const job=slideImageJob(r.id),working=imageWorking(job);
    const controls=editable()&&def.record&&!r.legacy?`${button('Edit labels','edit-slide','small',`data-id="${esc(r.id)}"`,'edit')}${def.type==='render'?button(working?'Creating photorealistic image…':'Make photorealistic','enhance-slide','primary small',`data-id="${esc(r.id)}" ${working?'disabled':''}`,'spark'):''}`:'';
    const sourceControls=`${r.image_version_id?`${button(original?'Show generated image':'Show original','toggle-slide-original','small ghost',`data-id="${esc(r.id)}"`,'eye')}${button(comparingImage(def)?'Show generated image':'Compare original & generated','toggle-slide-comparison','small ghost',`data-id="${esc(r.id)}"`,'image')}`:''}${button('Source & versions','history','small ghost',`data-id="${esc(f.id)}"`,'history')}`;
    const caption=`<div class="visual-caption"><span>${esc(source?.name||f.name)}${esc(location)}</span><div class="row wrap">${sourceControls}</div></div>`;
    const evidence=editable()&&r.metadata?.confidence==='low'?'<p class="visual-review-note">Suggested labels need a quick review. You can change the type and situation with Edit labels.</p>':'';
    if(def.type==='moodboard'){
        const colors=(r.metadata?.palette||[]).map(c=>c.hex).filter(c=>/^#[a-f0-9]{6}$/i.test(c));
        return `<div class="visual-toolbar"><div class="row wrap">${labels}</div><div class="row wrap">${controls}</div></div><section class="mood-slide individual-mood"><div><p class="slide-label">Mood & materials</p><h1 class="slide-heading">${esc(def.title)}</h1><p class="slide-description">${esc(r.description||t.style)}</p><div class="swatches">${(colors.length?colors:t.colors).map(c=>`<span class="swatch" style="background:${c}" title="${c}"></span>`).join('')}</div>${evidence}</div><button class="photo-magnify mood-magnify" data-action="magnify-photo" aria-label="Zoom in: ${esc(def.title)}">${img(f,def.title,'class="mood-image"')}<span class="photo-magnify-hint">${icon('expand')}Zoom in</span></button></section>${caption}`;
    }
    return `<div class="render-top"><div><div class="row wrap visual-labels">${labels}</div><h1 class="slide-heading">${esc(def.title)}</h1>${r.description?`<p class="slide-description">${esc(r.description)}</p>`:''}</div><div class="row wrap">${controls}</div></div>${f.has_preview||f.mime.startsWith('image/')?visualImageArea(def,f):empty('Source document','Download the original to see its contents.','download-current','Download original')}${caption}${job?.status==='failed'?`<p class="notice form-error" role="alert">The photorealistic image could not be created. ${esc(job.error)} Your current image is preserved.</p>`:''}${evidence}`;
}
function editSlideModal(id){const s=state.data.slides?.find(s=>s.id===id);if(!s||!requireDraft())return;openModal('Describe this slide',`<form data-form="slide-labels"><input type="hidden" name="slide_id" value="${esc(id)}"><label>Slide title<input name="title" value="${esc(s.title)}" maxlength="160" required></label><div class="field-row"><label>Image type<select name="type">${Object.entries(visualTypes).map(([k,v])=>`<option value="${k}" ${s.type===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Situation<select name="situation">${Object.entries(situations).map(([k,v])=>`<option value="${k}" ${s.situation===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div><p class="form-hint">A realistic rendering still represents a design concept unless the source says otherwise.</p>${s.metadata?.evidence?`<p class="notice">${esc(s.metadata.evidence)}</p>`:''}${formFooter('Save slide labels')}</form>`);}
function enhanceSlideModal(id){const s=state.data.slides?.find(s=>s.id===id);if(!s||s.type!=='render'||!requireDraft())return;openModal('Bring this rendering to life',`<p>Turn this render into an ultra-photorealistic image that looks photographed with a real camera, while preserving its design and viewpoint. The original image stays available.</p>${!state.data.capabilities.ai?'<p class="notice">Connect your AI service to create a photorealistic variation.</p>':''}<form data-form="slide-image-edit"><input type="hidden" name="slide_id" value="${esc(id)}"><label>Refine the rendering<textarea name="prompt" rows="4" maxlength="2000" required>Re-render this image as an ultra-photorealistic architectural photograph, indistinguishable from a real interior photographed with a professional camera. Use physically plausible natural and artificial lighting, realistic exposure and white balance, true-to-life reflections and contact shadows, fine material grain, fabric fibres, and subtle surface imperfections. Use natural lens perspective, realistic sharpness and restrained depth of field appropriate to interior photography. Remove the synthetic CGI look, plastic surfaces, overly perfect edges and artificial glow. Preserve the exact geometry, layout, furniture, finishes, colours, framing and camera position. Do not change the design or add objects.</textarea></label><div class="modal-footer">${button('Cancel','close-modal','ghost')}<button class="button primary" type="submit" ${state.data.capabilities.ai?'':'disabled'}>${icon('spark')}Make photorealistic</button></div></form>`);}
function openModal(title,content,wide=false){previousFocus=document.activeElement;activeModal=true;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2>${iconBtn('close','close-modal','Close dialog')}</div>${content}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input:not([type="hidden"]),.modal textarea,.modal button')?.focus(),20);}
function closeModal(){if(studioPreview){studioPreview=null;applyStudioTheme(state.studioTheme,!state.present&&!state.client);}activeModal=false;$('#overlay').innerHTML='';document.body.style.overflow='';previousFocus?.focus();}
function formFooter(label='Save',iconName='check'){return `<div class="modal-footer">${button('Cancel','close-modal','ghost')}<button class="button primary" type="submit">${icon(iconName)}${esc(label)}</button></div>`;}
function requireDraft(){if(state.data?.can_edit===false){toast('Only project team members can edit this project.');return false;}if(!editable()){iterationModal();return false;}return true;}
function newProjectModal(){openModal('A new project, a fresh start.',`<p>Give it a name. Add your clients. Then bring in your ideas.</p><form data-form="new-project"><label>Project name<input name="name" placeholder="Familie van Galen Werkhoven" required maxlength="160" autocomplete="off"></label><label>Visibility<select name="visibility"><option value="team">Team members only</option><option value="public">Public · everyone in this studio can view</option></select></label><label>Client email addresses<textarea name="emails" rows="2" placeholder="jack@example.com, partner@example.com" maxlength="2000"></textarea></label><p class="form-hint">Separate addresses with commas. Nothing is sent until you share.</p><div class="field-row"><label>Location <span class="muted">(optional)</span><input name="location" placeholder="Werkhoven, Netherlands" maxlength="160"></label><label>A short description <span class="muted">(optional)</span><input name="description" placeholder="A warm, considered family home" maxlength="2000"></label></div>${formFooter('Create project','arrow')}</form>`);}
function iterationModal(){const d=state.data;openModal('Room for the next iteration.',`<p>Create a new version of your presentation. All ${d.files.length} files carry forward; replace only what has changed.</p><form data-form="iteration"><label>Iteration name<input name="title" value="Design development" required maxlength="120"></label><p class="form-hint">Current client links stay attached to the iteration you shared.</p>${formFooter('Create iteration','plus')}</form><div class="section-title"><h2>Earlier iterations</h2></div>${(d.iterations||[]).map(i=>`<div class="history-item"><span>Concept ${i.number} · ${esc(i.title)}<small>${esc(i.status)} · ${esc(date(i.created_at))}</small></span>${button('Open','switch-iteration','small',`data-id="${esc(i.id)}"`)}</div>`).join('')}`);}
function originalsModal(){const id=slideDefs()[state.slide].id;openModal('The files behind this slide.',`<p>Download the source or explore its version history.</p><div class="download-list">${slideFiles(id).map(f=>`<button data-action="history" data-id="${esc(f.id)}"><span>${esc(f.name)}<small>Version ${f.number} · ${f.history.length} saved version${f.history.length===1?'':'s'}</small></span>${icon('right')}</button>`).join('')||'<p class="budget-note">No source files on this slide.</p>'}</div>`);}
function historyModal(id){const f=state.data.files.find(x=>x.id===id);if(!f)return;openModal('Every version, kept safe.',`<p>${esc(f.name)}</p>${f.history.map((v,n)=>`<div class="history-item"><div>Version ${v.number} ${n===0?'<span class="tag green">In this iteration</span>':''}<small>${esc(v.name)}${n===f.history.length-1?' · Original upload':''}</small></div>${button('Download','download','small',`data-id="${esc(v.id)}"`,'download')}</div>`).join('')}${f.metadata?.generated?`<p class="budget-note">AI change: ${esc(f.metadata.prompt)}</p>`:''}`);}
function budgetModal(id=''){if(id&&!state.data.budget.find(x=>x.id===id))return;const item=state.data.budget.find(x=>x.id===id)||{};const subs=state.data.budget.filter(x=>x.parent_id===id&&id);if(id){openModal(esc(item.label),`<p>${esc(item.vendor||'Vendor to be confirmed')}</p><div class="budget-total">${item.amount_cents===null?'To be specified':money(item.amount_cents)}</div><div class="row wrap" style="margin:15px 0"><span class="tag">${esc(item.kind)}</span>${Number(item.included)?'<span class="tag green">Already included in parent quote</span>':''}</div><p>${esc(item.note||'No additional source notes have been recorded.')}</p>${subs.length?`<div class="budget-section-label">Subquotes within this quote</div>${subs.map(s=>`<div class="history-item"><span>${esc(s.label)}<small>${esc(s.vendor)} · ${Number(s.included)?'Included':'Additional'}</small></span>${button(s.amount_cents===null?'TBC':money(s.amount_cents),'cost','small',`data-id="${esc(s.id)}"`)}</div>`).join('')}`:''}<div class="modal-footer">${item.source_version_id?button('Source quote','download','',`data-id="${esc(item.source_version_id)}"`,'download'):''}${!state.client?button('Edit cost','edit-cost','primary',`data-id="${esc(item.id)}"`,'edit'):button('Ask a question','feedback','primary','','chat')}</div>`);return;}editCostModal({});}
function editCostModal(item){if(!requireDraft())return;const excluded=new Set([item.id]);let changed=true;while(changed){changed=false;for(const x of state.data.budget)if(excluded.has(x.parent_id)&&!excluded.has(x.id)){excluded.add(x.id);changed=true;}}openModal(item.id?'Refine this cost.':'Make the numbers clearer.',`<form data-form="budget"><input type="hidden" name="id" value="${esc(item.id||'')}"><label>Cost or quote<input name="label" value="${esc(item.label||'')}" placeholder="Custom kitchen cabinetry" required maxlength="300"></label><label>Vendor<input name="vendor" value="${esc(item.vendor||'')}" placeholder="Company or supplier" maxlength="200"></label><div class="field-row"><label>Amount (€)<input name="amount" type="number" step="0.01" value="${item.amount_cents!=null?item.amount_cents/100:''}" placeholder="Leave empty if unknown"></label><label>Status<select name="kind">${[['quote','Quoted'],['estimate','Estimated'],['unknown','Unspecified']].map(([v,t])=>`<option value="${v}" ${v===item.kind?'selected':''}>${t}</option>`).join('')}</select></label></div><label>Part of another quote?<select name="parent_id"><option value="">Separate project cost</option>${state.data.budget.filter(x=>!excluded.has(x.id)).map(x=>`<option value="${esc(x.id)}" ${item.parent_id===x.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label><label class="check-label"><input name="included" type="checkbox" ${Number(item.included)?'checked':''}>Included in the parent quote’s total</label><label>Notes & exclusions<textarea name="note" rows="2" placeholder="VAT, scope, exclusions, validity…" maxlength="2000">${esc(item.note||'')}</textarea></label>${formFooter('Save cost')}</form>`);}
function feedbackModal(){const slide=state.present?slideDefs()[state.slide].id:'general',comments=state.data.comments.filter(c=>c.slide===slide||slide==='general');openModal('Let’s make it feel right.',`<p>A question, a suggestion, something you love. ${state.present?'Your feedback will be attached to this slide.':'Leave a note for this iteration.'}</p><div class="feedback-list">${comments.map(c=>`<article class="feedback-item"><small>${esc(c.author)} · ${esc(date(c.created_at))}</small>${esc(c.body)}</article>`).join('')}</div><form data-form="feedback"><input type="hidden" name="slide" value="${slide}"><label>Your thoughts<textarea name="body" rows="4" placeholder="Could we explore a warmer finish for the kitchen?" maxlength="4000" required></textarea></label>${formFooter('Add feedback','chat')}</form>`);}
function shareModal(){const d=state.data,emails=d.contacts.filter(x=>x.role==='Client').map(x=>x.email);openModal('Ready for their first look?',`${DEMO?'<div class="notice">Demo mode: no email will be sent. You can explore the client view and sharing flow. Changes last for this session.</div>':''}<p>Share concept ${d.iteration.number} with your clients. They can open it directly, explore the budget, and leave feedback.</p><form data-form="share"><label>Client email addresses<textarea name="emails" rows="2" required>${esc(emails.join(', '))}</textarea></label><p class="form-hint">Each address receives its own private link, valid for 90 days. Sharing preserves this iteration; further changes go into a new one.</p>${!d.capabilities.mail&&!DEMO?'<div class="notice">Email delivery is not configured. Links will be created for you to copy and send.</div>':''}<label class="check-label"><input type="checkbox" required>I’ve reviewed the slides, source amounts and unknown costs.</label><div class="modal-footer">${button('Preview first','preview','')}<button type="submit" class="button primary" ${pending()?'disabled':''}>${icon('send')}${d.capabilities.mail?'Send to clients':'Create client links'}</button></div></form>`);}
function contactsModal(){openModal('The people behind this project.',`${state.data.contacts.map(c=>`<div class="history-item"><span>${esc(c.name)}<small>${esc(c.role)} · ${esc(c.email)}</small></span><a class="icon-button" href="mailto:${esc(encodeURIComponent(c.email))}" aria-label="Email ${esc(c.name)}">${icon('mail')}</a></div>`).join('')}<div class="modal-footer">${button('Add contact','add-contact','primary','','plus')}</div>`);}
function addContactModal(){openModal('Add someone to the team.',`<form data-form="contact"><label>Name<input name="name" required maxlength="100"></label><label>Email<input name="email" type="email" required maxlength="254"></label><div class="field-row"><label>Role<select name="role"><option>Architect</option><option>Interior designer</option><option>Contractor</option><option>Client</option><option>Supplier</option></select></label><label>Phone <span class="muted">(optional)</span><input name="phone" type="tel" maxlength="40"></label></div>${formFooter('Add contact','plus')}</form>`);}
let studioPreview=null;
function studioSettings(){
    const t=cleanStudioTheme(state.studioTheme);
    openModal('Studio appearance',`<p>Choose the look of your private workspace. Changes preview immediately. Each project keeps its own presentation style.</p><form data-form="studio-theme"><fieldset class="studio-options"><legend>Color palette</legend><div class="studio-palette-options">${Object.entries(studioPalettes).map(([key,p])=>`<label class="studio-choice"><input type="radio" name="palette" value="${key}" ${t.palette===key?'checked':''}><span class="studio-palette-sample">${p.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span><span>${esc(p.name)}</span></label>`).join('')}</div></fieldset><fieldset class="studio-options"><legend>Style</legend><div class="studio-style-options">${Object.entries(studioStyles).map(([key,name])=>`<label class="studio-choice studio-style-${key}"><input type="radio" name="style" value="${key}" ${t.style===key?'checked':''}><strong>${name}</strong><small>${{classic:'Elegant serif headings',modern:'Clean, contemporary type',minimal:'Quiet lines, compact corners',editorial:'Expressive type and space'}[key]}</small></label>`).join('')}</div></fieldset><p class="studio-preview-note" role="status">Live preview · Save to keep this look across your projects.</p>${formFooter('Save studio appearance')}</form>`);
    studioPreview=t;
}
document.addEventListener('change',e=>{const form=e.target.closest('[data-form="studio-theme"]');if(!form)return;studioPreview=cleanStudioTheme(Object.fromEntries(new FormData(form)));applyStudioTheme(studioPreview,!state.present&&!state.client);});
function previewBar(){return !state.client?`<div class="preview-bar">${button('Back to studio','exit-preview','ghost small','','left')}<span>Presentation preview</span></div>`:'';}
function themeModal(){if(!requireDraft())return;const t=theme();openModal('A presentation that feels like you.',`<p>The palette follows your moodboard. Refine it before sharing.</p>${state.data.project.theme?.reason?`<p class="notice">${esc(state.data.project.theme.reason)}</p>`:''}<form data-form="theme"><label>Design direction<input name="style" value="${esc(t.style)}" maxlength="40" required></label><label>Presentation typography<select name="font"><option value="serif" ${t.font==='serif'?'selected':''}>Editorial serif · warm & classic</option><option value="sans" ${t.font==='sans'?'selected':''}>Modern sans · clean & minimal</option></select></label><label>Project palette</label><div class="theme-editor-swatches">${t.colors.map((c,n)=>`<input type="color" name="color${n}" value="${c}" aria-label="Palette color ${n+1}">`).join('')}</div>${formFooter('Apply to presentation','check')}</form>`);}
function editImageModal(id,enhance=false){const f=state.data.files.find(x=>x.id===id);if(!f||!requireDraft())return;openModal(enhance?'Bring the light to life.':'Explore another possibility.',`${!state.data.capabilities.ai?'<div class="notice">Image editing needs the AI connection in the PHP application. Your original is preserved; each result becomes another version.</div>':''}<p>Describe the change. The current image and all earlier versions stay available.</p><form data-form="image-edit"><input type="hidden" name="version_id" value="${esc(id)}"><label>What would you like to change?<textarea name="prompt" rows="4" required maxlength="2000">${enhance?'Make this 3D interior render photorealistic. Improve natural lighting, realistic material textures and shadows. Preserve the design, furniture, colours and camera position.':''}</textarea></label><p class="form-hint">For example: “Change only the kitchen cabinet fronts to dark walnut.” AI results are visual studies; review them before sharing.</p><div class="modal-footer">${button('Close','close-modal','ghost')}<button class="button primary" type="submit" ${state.data.capabilities.ai?'':'disabled'}>${icon('spark')}Create a new version</button></div></form>`);}
function manageLinks(){const shares=state.data.shares||[];openModal('Your shared presentations.',`<p>Each link opens only the iteration it was created for. Revoke a link to stop access.</p>${shares.map(s=>`<div class="history-item"><span>${esc(s.email)}<small>${s.revoked?'Revoked':'Expires '+new Date(s.expires_at*1000).toLocaleDateString('en-GB')}</small></span>${s.revoked?'':button('Revoke','revoke-share','small',`data-id="${esc(s.id)}"`)}</div>`).join('')||'<p class="muted">There are no active links recorded for this iteration.</p>'}<div class="modal-footer">${button('Share presentation','share','primary','','send')}</div>`);}
async function download(id){let name,url;if(DEMO){const f=demoFile(id);if(!f)throw Error('This source is not available.');name=f.name;url=f.url;}else{const f=state.data.files.flatMap(f=>[f,...f.history]).find(v=>v.id===id);if(!f)throw Error('This source is not part of this iteration.');const p=new URLSearchParams({action:'file',id,iteration:state.data.iteration.id}),headers=state.shareToken?{Authorization:'Bearer '+state.shareToken}:{};const r=await fetch('api.php?'+p,{credentials:'same-origin',headers});if(!r.ok){const b=await r.json();throw Error(b.error||'Download unavailable.');}name=f.name;url=URL.createObjectURL(await r.blob());}const a=document.createElement('a');a.href=url;a.download=name;a.click();if(!DEMO)setTimeout(()=>URL.revokeObjectURL(url),20000);}
async function uploadFiles(files,asset=''){if(!files.length||!requireDraft())return;if(files.length>20)throw Error('Drop up to 20 files at a time.');if(files.reduce((n,f)=>n+f.size,0)>120*1024*1024)throw Error('Keep each batch below 120 MB.');const fd=new FormData();fd.append('iteration',state.data.iteration.id);if(asset)fd.append('replace_asset',asset);for(const f of files)fd.append('files[]',f);
    showProcessing(true);
    try{const result=await api('upload',fd);processingView.uploading=false;processingView.ids=result.ids||[];state.tab='overview';await refresh();renderProcessing();}
    catch(e){processingView.uploading=false;processingView.error=e.message;renderProcessing();throw e;}
}
function chooseFiles(asset=''){if(!requireDraft())return;const input=document.createElement('input');input.type='file';input.multiple=!asset;input.accept='.pdf,.ppt,.pptx,.xls,.xlsx,.csv,.jpg,.jpeg,.png,.webp';input.addEventListener('change',()=>uploadFiles([...input.files],asset).catch(e=>toast(e.message)));input.click();}
async function askBudget(q){if(state.busy)return;state.chat.push({role:'user',text:q});state.busy=true;render();try{const r=await api('budget_chat',{iteration:state.data.iteration.id,question:q});state.chat.push({role:'assistant',text:r.answer,sources:r.sources});}catch(e){state.chat.push({role:'assistant',text:e.message});}finally{state.busy=false;render();$('#chat-messages')?.scrollTo(0,99999);}}
function startPresentation(slide=0){if(activeModal)closeModal();if(!slideDefs().length){toast('Show a slide in the editor before previewing.');return;}state.present=true;state.slide=Math.max(0,slide);state.imageIndex=0;state.zoom=1;render();window.scrollTo(0,0);api('view_event',{iteration:state.data.iteration.id,slide:slideDefs()[state.slide].id}).catch(()=>{});}
function moveSlide(n){state.slide=Math.max(0,Math.min(state.slide+n,slideDefs().length-1));state.imageIndex=0;state.zoom=1;render();window.scrollTo(0,0);}
function showInfo(kind){if(kind==='demo')openModal('Meet Studiodeck.',`<p>This is a working interface demo with a fictional family project. Explore the presentation, expand the budget, leave feedback, or create a project and try the drop area.</p><div class="notice">Demo changes last for this page session. Emails, document extraction and AI image generation are not connected here.</div><p>The accompanying PHP application stores records and file versions in SQLite, processes uploaded documents, and supports email and AI connections.</p><div class="modal-footer">${button('Explore the client view','preview','primary','','play')}</div>`);else openModal('From a folder to a story.',`<div class="stack"><p><strong>1. Create a project.</strong><br>Name it and add your clients’ email addresses.</p><p><strong>2. Bring your files.</strong><br>Drop in presentations, drawings, moodboards and quotes. Review the categories and extracted costs.</p><p><strong>3. Make it yours.</strong><br>Preview the deck, adjust its palette and clarify any unknown costs.</p><p><strong>4. Share a moment.</strong><br>Send a private client link. Collect feedback, then create a new iteration when your design develops.</p></div>`);}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;try{switch(a){
case 'close-modal':pageReviewSequence++;closeModal();break;
case 'show-processing':showProcessing();break;
case 'hide-processing':hideProcessing();break;
case 'review-processed':hideProcessing();state.tab='files';render();break;
case 'toggle-extracted':expandedFiles.has(el.dataset.id)?expandedFiles.delete(el.dataset.id):expandedFiles.add(el.dataset.id);render();document.querySelector(`[data-action="toggle-extracted"][data-id="${CSS.escape(el.dataset.id)}"]`)?.focus();break;
case 'preview-extracted':await previewExtracted(el.dataset.id);break;
case 'download-extracted':await downloadExtracted(el.dataset.id);break;
case 'review-pages':await reviewPage(el.dataset.id);break;
case 'edit-slide':editSlideModal(el.dataset.id);break;
case 'slide-view':state.slideView=el.dataset.view;render();break;
case 'open-editor-slide':openEditorSlide(el.dataset.id);break;
case 'zoom-editor-slide':openEditorSlide(el.dataset.id,true);break;
case 'visibility-slide':await changeSlideLayout(el.dataset.operation,{slide_id:el.dataset.id});break;
case 'move-editor-slide':await reorderEditorSlide(el.dataset.id,editorSlides().findIndex(s=>s.id===el.dataset.id)+Number(el.dataset.direction));break;
case 'delete-slide':{const s=editorSlides().find(s=>s.id===el.dataset.id);if(!s||!requireDraft())break;openModal('Delete this slide?',`<p>Remove <strong>${esc(s.title)}</strong> from this presentation? The original file stays in Files.</p><div class="modal-footer">${button('Cancel','close-modal','ghost')}${button('Delete slide','confirm-delete-slide','danger-text',`data-id="${esc(s.id)}"`)}</div>`);break;}
case 'confirm-delete-slide':await changeSlideLayout('delete',{slide_id:el.dataset.id});closeModal();toast('Slide removed. The original file is still available.');break;
case 'magnify-photo':openPhotoLightbox();break;
case 'close-photo':closePhotoLightbox();break;
case 'next-photo-slide':navigatePhotoLightbox(1);break;
case 'previous-photo-slide':navigatePhotoLightbox(-1);break;
case 'enhance-slide':enhanceSlideModal(el.dataset.id);break;
case 'toggle-slide-comparison':if(showOriginalSlides.has(el.dataset.id)||showGeneratedSlides.has(el.dataset.id)){showOriginalSlides.delete(el.dataset.id);showGeneratedSlides.delete(el.dataset.id);}else showGeneratedSlides.add(el.dataset.id);render();if(magnifiedPhoto)renderPhotoLightbox();break;
case 'toggle-slide-original':if(showOriginalSlides.has(el.dataset.id)){showOriginalSlides.delete(el.dataset.id);showGeneratedSlides.add(el.dataset.id);}else showOriginalSlides.add(el.dataset.id);render();if(magnifiedPhoto)renderPhotoLightbox();break;
case 'reprocess':{if(!requireDraft())break;const r=await api('reprocess',{iteration:state.data.iteration.id,version_id:el.dataset.id});showProcessing(false,[r.id]);await refresh();break;}
case 'demo-info':showInfo('demo');break;
case 'settings':studioSettings();break;
case 'studio-users':state.studioUsers=(await api('studio_users')).users;state.tab='studio-users';state.present=false;render();break;
case 'new-studio':openModal('Create a studio',`<form data-form="new-studio"><label>Studio name<input name="name" required maxlength="100"></label>${formFooter('Create studio')}</form>`);break;
case 'edit-studio-user':studioUserModal(el.dataset.id);break;
case 'remove-studio-user':openModal('Remove studio member?',`<p>This removes access to this studio and its project teams. Their account in other studios is preserved.</p><form data-form="remove-studio-user"><input type="hidden" name="id" value="${esc(el.dataset.id)}">${formFooter('Remove member')}</form>`);break;
case 'project-team':await projectTeamModal();break;
case 'help':showInfo('help');break;
case 'menu':$('.sidebar')?.classList.toggle('open');break;
case 'projects':await loadProjects();state.tab='projects';state.present=false;render();pollJobs();break;
case 'project-settings':projectSettingsModal();break;
case 'pin-project':await api('pin_project',{project_id:el.dataset.id,pinned:el.dataset.pinned==='1'});await loadProjects();render();break;
case 'archive-project':await api('project_settings',{project_id:el.dataset.id,archived:el.dataset.archived==='1'});await loadProjects();render();break;
case 'open-project':state.tab='overview';await openProject(el.dataset.id);break;
case 'tab':if(!state.data){toast('Create or open a project first.');break;}state.tab=el.dataset.tab;state.present=false;render();break;
case 'new-project':newProjectModal();break;
case 'preview':state.inspectHidden=false;startPresentation();break;
case 'go-slide':startPresentation(Number(el.dataset.slide));break;
case 'next-slide':moveSlide(1);break;
case 'prev-slide':moveSlide(-1);break;
case 'exit-preview':state.present=false;document.documentElement.style.removeProperty('--heading');render();break;
case 'upload':chooseFiles();break;
case 'replace':{const f=state.data.files.find(x=>x.id===el.dataset.id);chooseFiles(f.asset_id);break;}
case 'filter':state.filter=el.dataset.filter;render();break;
case 'download':await download(el.dataset.id);break;
case 'download-current':{const fs=slideFiles(slideDefs()[state.slide].id);if(fs.length)await download(fs[0].id);break;}
case 'history':historyModal(el.dataset.id);break;
case 'originals':originalsModal();break;
case 'iteration':iterationModal();break;
case 'switch-iteration':closeModal();await openProject(state.data.project.id,el.dataset.id);break;
case 'theme':themeModal();break;
case 'share':shareModal();break;
case 'copy-link':await navigator.clipboard.writeText(el.dataset.url);toast('Link copied.');break;
case 'client-view':closeModal();state.client=true;state.shareToken=DEMO?'':state.shareToken;startPresentation();break;
case 'contacts':contactsModal();break;
case 'add-contact':addContactModal();break;
case 'feedback':feedbackModal();break;
case 'add-cost':budgetModal();break;
case 'cost':budgetModal(el.dataset.id);break;
case 'edit-cost':editCostModal(state.data.budget.find(x=>x.id===el.dataset.id));break;
case 'toggle-cost':state.openCosts.has(el.dataset.id)?state.openCosts.delete(el.dataset.id):state.openCosts.add(el.dataset.id);render();break;
case 'ask':await askBudget(el.dataset.question);break;
case 'enhance':editImageModal(el.dataset.id,true);break;
case 'image-edit':editImageModal(el.dataset.id);break;
case 'image-index':state.imageIndex=Number(el.dataset.index);state.zoom=1;render();break;
case 'next-image':state.imageIndex=(state.imageIndex+1)%photoFiles().length;render();break;
case 'prev-image':state.imageIndex=(state.imageIndex-1+photoFiles().length)%photoFiles().length;render();break;
case 'zoom-in':state.zoom=Math.min(3,state.zoom+.25);render();break;
case 'zoom-out':state.zoom=Math.max(.5,state.zoom-.25);render();break;
case 'zoom-reset':state.zoom=1;render();break;
case 'manage-links':manageLinks();break;
case 'revoke-share':await api('revoke_share',{id:el.dataset.id});closeModal();await refresh();toast('Client link revoked.');break;
case 'job-status':openModal('A closer look at your files.',(state.data.jobs||[]).filter(j=>j.status==='failed').map(j=>`<div class="history-item"><span>${esc(j.type)}<small>${esc(j.error)}</small></span>${button('Retry','retry-job','small',`data-id="${esc(j.id)}"`)}</div>`).join(''));break;
case 'retry-job':await api('retry_job',{id:el.dataset.id});closeModal();await refresh();toast('Processing queued again.');break;
case 'logout':if(DEMO){showInfo('demo');break;}await api('logout');state.user=null;state.data=null;state.present=false;state.client=false;render();break;
}}catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),type=form.dataset.form;if(type==='chat'){await askBudget(data.question);return;}form.querySelector('.form-error')?.remove();const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;
 try{const iid=state.data?.iteration.id;
  if(type==='project-settings'){await api('project_settings',{project_id:state.data.project.id,visibility:data.visibility});closeModal();await refresh();}
  if(type==='new-studio'){applySession(await api('create_studio',data));closeModal();await resetStudio();}
  if(type==='studio-user'){state.studioUsers=(await api('save_studio_user',data)).users;closeModal();applySession(await api('session'));render();}
  if(type==='remove-studio-user'){await api('remove_studio_user',data);closeModal();applySession(await api('session'));await resetStudio();}
  if(type==='project-team'){await api('project_members',{project_id:state.data.project.id,user_ids:new FormData(form).getAll('user_ids')});closeModal();await resetStudio();}
  if(type==='new-project'){const emails=data.emails.split(/[,;\n]/).map(x=>x.trim()).filter(Boolean);if(emails.some(x=>!/^\S+@\S+\.\S+$/.test(x)))throw Error('Please check the client email addresses.');const r=await api('create_project',{...data,emails});closeModal();state.tab='files';state.projects=(await api('projects')).projects;await openProject(r.project_id);toast('Your project is ready. Drop in your first files.');}
  if(type==='iteration'){const r=await api('new_iteration',{iteration:iid,title:data.title});closeModal();await openProject(state.data.project.id,r.id);toast('New iteration created. All existing files carried forward.');}
  if(type==='budget'){if(data.parent_id&&data.parent_id===data.id)throw Error('A quote cannot contain itself.');await api('save_budget',{...data,iteration:iid,included:data.included==='on'});closeModal();await refresh();toast('Cost saved.');}
  if(type==='contact'){await api('save_contact',{...data,project_id:state.data.project.id});closeModal();await refresh();toast('Contact added.');}
  if(type==='studio-theme'){const r=await api('studio_theme',{theme:cleanStudioTheme(data)});state.studioTheme=r.studio_theme;studioPreview=null;closeModal();render();toast('Studio appearance saved.');}
  if(type==='theme'){const colors=Object.entries(data).filter(([k])=>k.startsWith('color')).map(([,v])=>v);await api('theme',{iteration:iid,theme:{style:data.style,font:data.font,colors}});closeModal();await refresh();toast('Presentation styling updated.');}
  if(type==='feedback'){await api('comment',{iteration:iid,slide:data.slide,body:data.body});closeModal();await refresh();toast(DEMO?'Feedback saved for this demo session.':'Your feedback has been added.');}
  if(type==='share'){const emails=data.emails.split(/[,;\n]/).map(x=>x.trim()).filter(Boolean);if(emails.some(x=>!/^\S+@\S+\.\S+$/.test(x)))throw Error('Please check the email addresses.');const r=await api('share',{iteration:iid,emails});await refresh();openModal(r.links.every(x=>x.sent)?'It’s on its way.':'Your client links are ready.',`${DEMO?'<div class="notice">Demo links open the example presentation. No email was sent. New project data is not shared across browsers.</div>':'<p>Copy any link to send it yourself. Keep it private: anyone with a link can view that iteration.</p>'}${r.links.map(l=>`<div class="link-result"><strong>${esc(l.email)}</strong><small>${l.sent?'Sent by email':'Not emailed · copy this link to send'}</small><div class="row"><input value="${esc(l.url)}" readonly aria-label="Client presentation link">${button('Copy','copy-link','small',`data-url="${esc(l.url)}"`,'copy')}</div></div>`).join('')}<div class="modal-footer">${DEMO?button('Try the client view','client-view','primary','','eye'):button('Done','close-modal','primary','','check')}</div>`);}
  if(type==='slide-labels'){await api('save_slide',{...data,iteration:iid});closeModal();await refresh();toast('Slide labels updated.');}
  if(type==='slide-image-edit'){showOriginalSlides.delete(data.slide_id);showGeneratedSlides.delete(data.slide_id);await api('slide_image_edit',{...data,iteration:iid,mode:'photorealistic'});closeModal();await refresh();toast('Creating a photorealistic variation of this render.');}
  if(type==='image-edit'){await api('image_edit',{iteration:iid,version_id:data.version_id,prompt:data.prompt});closeModal();await refresh();toast('Your image variation is being created.');}
  if(type==='login'){const r=await api('request_login',{email:data.email,name:data.email.split('@')[0]});form.innerHTML=`<div class="notice">${esc(r.message)}</div>`;}
  if(type==='consume-login'){await api('consume_login',{token:data.token});history.replaceState(null,'',location.pathname);await start();}
 }catch(error){const div=document.createElement('div');div.className='form-error';div.setAttribute('role','alert');div.textContent=error.message;form.prepend(div);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('change',async e=>{try{if(e.target.id==='document-page-select')await reviewPage(e.target.dataset.version,Number(e.target.value));if(e.target.id==='iteration-select')await openProject(state.data.project.id,e.target.value);if(e.target.matches('[data-category]')){await api('category',{iteration:state.data.iteration.id,asset_id:e.target.dataset.category,category:e.target.value});await refresh();toast('Category updated.');}}catch(error){toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='file-search'){const pos=e.target.selectionStart;state.search=e.target.value;renderWorkspace();const input=$('#file-search');input?.focus();input?.setSelectionRange(pos,pos);}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action]'))return;const dz=e.target.closest('[data-dropzone]');if(dz){chooseFiles();return;}if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('dragover',e=>{const dz=e.target.closest('[data-dropzone]');if(dz){e.preventDefault();dz.classList.add('dragging');}});
document.addEventListener('dragleave',e=>{const dz=e.target.closest('[data-dropzone]');if(dz&&!dz.contains(e.relatedTarget))dz.classList.remove('dragging');});
document.addEventListener('drop',e=>{const dz=e.target.closest('[data-dropzone]');if(dz){e.preventDefault();dz.classList.remove('dragging');uploadFiles([...e.dataTransfer.files]).catch(error=>toast(error.message));}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(activeModal)closeModal();else if(state.present&&!state.client){state.present=false;render();}$('.sidebar')?.classList.remove('open');}
 if(activeModal&&e.key==='Tab'){const list=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not([type="hidden"]):not(:disabled),.modal select,.modal textarea,.modal a')];if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
 if(e.target.closest('input,textarea,select')||activeModal)return;
 if(state.present&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){e.preventDefault();moveSlide(e.key==='ArrowRight'?1:-1);}
 if(e.target.matches('[data-dropzone]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();chooseFiles();}
});
function renderLogin(token=''){const hasToken=!!token;$('#app').innerHTML=`<main class="login" id="main"><div class="login-image"><img src="assets/interior.webp" alt="A warm, light-filled interior"></div><div class="login-content">${brand()}<h1>${hasToken?'Your studio awaits.':'Good design.<br>Beautifully together.'}</h1><p>${hasToken?'One click, and you’re back in your creative space.':'Your projects, presentations and clients. One considered space.'}</p><form data-form="${hasToken?'consume-login':'login'}">${hasToken?`<input type="hidden" name="token" value="${esc(token)}">`:'<label>Your email address<input type="email" name="email" placeholder="you@yourstudio.com" autocomplete="email" required></label>'}<button class="button primary wide" type="submit">${hasToken?'Open my studio':'Email me a sign-in link'}${icon('arrow')}</button><small>No password to remember. Your sign-in lasts 14 days on this device.</small></form></div></main>`;}
async function start(){try{const match=location.hash.match(/^#\/(view|login|preview)\/([^/]+)$/);if(match?.[1]==='login'){renderLogin(match[2]);return;}
  if(match?.[1]==='view'){state.client=true;state.shareToken=match[2];state.data=await api('deck');state.present=true;state.slide=0;render();api('view_event',{iteration:state.data.iteration.id,slide:'intro'}).catch(()=>{});return;}
  const session=await api('session');applySession(session);if(!state.user){renderLogin();return;}state.projects=(await api('projects')).projects;
  if(match?.[1]==='preview'){state.data=await api('deck',{iteration:match[2]});startPresentation();return;}
  state.tab='projects';render();pollJobs();
 }catch(error){$('#app').innerHTML=`<main class="error-page" id="main">${brand()}<h1>This presentation isn’t available.</h1><p>${esc(error.message)}</p><a class="button primary" href="${esc(location.pathname)}">Return to the studio</a></main>`;}}
let processingView={visible:false,uploading:false,ids:[],iteration:null};
let processingFocus=null;
function processingJobs(){return (state.data?.jobs||[]).filter(j=>!processingView.ids.length||processingView.ids.includes(j.version_id));}
function processingDescription(){const job=(state.data?.jobs||[]).find(j=>j.status==='running')||(state.data?.jobs||[]).find(j=>j.status==='queued');if(job?.type==='slide_image_edit'||job?.type==='image_edit')return 'Creating a photorealistic image · The result will appear on its slide';const p=extractionProgress(job);return `${p.title} · ${p.detail} · ${p.percent}%`; }
function processingBanner(){return pending()?`<div class="notice processing-banner"><span class="loading-inline" aria-hidden="true"></span><span role="status">${esc(processingDescription())}</span>${button('View progress','show-processing','small')}</div>`:'';}
function showProcessing(uploading=false,ids=[]){
    processingFocus=document.activeElement;
    processingView={visible:true,uploading,ids,iteration:state.data?.iteration.id};
    if(activeModal)closeModal();
    renderProcessing();$('#processing-overlay [data-action="hide-processing"]')?.focus();
}
function hideProcessing(){processingView.visible=false;$('#processing-overlay')?.remove();$('#app').inert=false;$('#overlay').inert=false;document.body.classList.remove('processing-open');if(processingFocus?.isConnected)processingFocus.focus();}
function renderProcessing(){
    if(!processingView.visible)return;
    if(processingView.iteration!==state.data?.iteration.id){hideProcessing();return;}
    let root=$('#processing-overlay');
    if(!root){root=document.createElement('div');root.id='processing-overlay';root.className='processing-overlay';root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-labelledby','processing-title');root.innerHTML=`<button class="icon-button processing-close" data-action="hide-processing" aria-label="Close processing overlay">${icon('close')}</button><div class="processing-content"></div>`;document.body.append(root);}
    $('#app').inert=true;$('#overlay').inert=true;document.body.classList.add('processing-open');
    const jobs=processingJobs(),active=jobs.find(j=>j.status==='running')||jobs.find(j=>j.status==='queued'),complete=jobs.length&&!active&&!processingView.uploading,failed=jobs.filter(j=>j.status==='failed'),done=jobs.filter(j=>j.status==='done').length;
    const warningCount=jobs.reduce((n,j)=>n+(j.progress?.warning_count||0),0);
    const imageJob=active&&['slide_image_edit','image_edit'].includes(active.type);
    const progress=active?.progress,stage=processingView.uploading?'uploading':active?.status==='queued'?'queued':progress?.stage||'reading_pages';
    const heading=processingView.error?'Upload needs attention':complete?(failed.length?'Some files need your attention':'Your files are ready to review'):imageJob?'Creating your photorealistic image':extractionStages[stage]||'Processing your files';
    const overall=extractionProgress(active),section=overall.step;
    const content=`<div class="processing-art ${complete||processingView.error?'is-complete':''}" aria-hidden="true"><span></span><span></span><span>${icon(complete?'check':'file')}</span><i></i></div><p class="eyebrow">BRINGING YOUR PROJECT TOGETHER</p><h1 id="processing-title">${esc(heading)}</h1><p class="processing-detail" role="status">${esc(processingView.error|| (complete?`${done} file${done===1?'':'s'} processed. Explore the extracted pages, images and palette.`:active?.name||'Your originals are being safely stored.'))}${!complete&&!processingView.uploading?`<br>${imageJob?'Refining light, textures & shadows. The result will appear on its slide.':esc(overall.detail)}`:''}</p>${!imageJob?`<ol class="processing-stages">${processingSteps.map((label,n)=>`<li class="${!complete&&n===section?'current':complete||n<section?'finished':''}"><span>${complete||n<section?icon('check'):n+1}</span>${label}</li>`).join('')}</ol>`:''}${!complete&&!processingView.error&&!processingView.uploading&&!imageJob?`<div class="processing-track determinate" role="progressbar" aria-label="File processing progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${overall.percent}" aria-valuetext="${esc(overall.detail)}"><span style="width:${overall.percent}%"></span></div><p class="processing-percent">${overall.percent}% of this file · Larger documents can take several minutes.</p>`:''}<p class="processing-count">${jobs.length?`${done} of ${jobs.length} files completed`:processingView.uploading?'Uploading…':''}</p>${complete&&warningCount?`<p class="notice">${warningCount} extraction note${warningCount===1?'':'s'} to review in Files.</p>`:''}${failed.map(j=>`<p class="form-error">${esc(j.name)}: ${esc(j.error)}</p>`).join('')}<div class="processing-footer">${complete?button('Review files','review-processed','primary','','arrow'):button('Continue working','hide-processing','primary','','arrow')}<p>${complete?'Open any document to inspect its pages and images.':'Slides appear when each file finishes. You can close this view; processing continues in the background.'}</p></div>`;
    // Keep focused controls and the animation alive between identical polling results.
    const target=root.querySelector('.processing-content');if(target.dataset.content!==content){target.innerHTML=content;target.dataset.content=content;}
}
function pageVisuals(category){return (state.data?.files||[]).flatMap(f=>{const pages=(f.pages||[]).filter(p=>p.has_preview&&(p.category===category||(f.category===category&&(!p.category||['other','presentation'].includes(p.category)))||(category==='presentation'&&f.category===category)));return pages.length?pages.map(p=>({...f,page_number:p.number,name:`${f.name} · Page ${p.number}`,has_preview:true})):f.category===category&&!f.pages?.length?[f]:[];});}
const imageKey=f=>`${f.id}${f.page_number?'@'+f.page_number:''}${f.image_number?'@'+f.image_number:''}${f.slide_image_version&&!f.show_original?'@variant-'+f.slide_image_version:''}`;
function imageSlideCaption(version,page,image){const defs=slideDefs(),index=defs.findIndex(s=>s.record&&s.record.source_version_id===version&&s.record.page_number===page&&s.record.image_number===image);if(index<0)return '';const s=defs[index];return `<div class="image-slide-label">${esc(visualTypes[s.type])} · ${esc(situations[s.situation])}</div>${button('View slide','go-slide','small ghost',`data-slide="${index}"`,'slide')}`;}
let pageReviewSequence=0;
async function reviewPage(id,number=1){
    const f=state.data.files.find(f=>f.id===id);if(!f)return;
    const sequence=++pageReviewSequence;
    openModal('Inside your document',`<p>${esc(f.name)}</p><p><span class="loading-inline"></span> Opening page ${number}…</p>`);
    if(!f.pages?.length){openModal('Inside your document',`<p>${esc(f.name)}</p><p>This file has no extracted pages yet.</p>${editable()?button('Extract pages & images','reprocess','primary',`data-id="${esc(id)}"`,'spark'):''}${(f.metadata?.warnings||[]).map(w=>`<p class="notice">${esc(w)}</p>`).join('')}`);return;}
    const p=await api('document_page',{iteration:state.data.iteration.id,id,page:number});
    if(sequence!==pageReviewSequence||!activeModal)return;
    const meta=p.metadata||{},suggestion=meta.analysis||{},pageImage={...f,page_number:number};
    openModal('Inside your document',`<p>${esc(f.name)}</p><div class="page-review-nav"><label>Page<select id="document-page-select" data-version="${esc(id)}">${f.pages.map(page=>`<option value="${page.number}" ${page.number===number?'selected':''}>${page.number} of ${f.metadata?.page_count||f.pages.length}</option>`).join('')}</select></label><span>${p.images.length} extracted image${p.images.length===1?'':'s'}</span>${editable()?button('Extract again','reprocess','small',`data-id="${esc(id)}"`,'spark'):''}</div>${meta.extraction_plan?`<div class="notice page-plan-note"><strong>Page type: ${esc(meta.extraction_plan.content_type)} · ${meta.extraction_plan.strategy==='preserve'?'Composition kept intact':meta.extraction_plan.strategy==='separate'?'Independent images':'No project images'}</strong><p>${esc(meta.extraction_plan.reason)}</p>${meta.extraction_plan.excluded?.length?`<small>${meta.extraction_plan.excluded.length} branding / decorative region(s) excluded.</small>`:''}</div>`:''}<div class="page-review-grid"><div class="page-review-preview">${p.has_preview?img(pageImage,'Page '+number+' of '+f.name):'<p class="notice">Slide preview unavailable. Extracted text and images are below.</p>'}</div><div><h3>Text on this page</h3>${meta.text_blocks?.some(b=>b.source==='ocr')?'<p class="form-hint">Includes text read from images. Check it against the page.</p>':''}<pre class="extracted-text">${esc(p.text||'No readable text found on this page.')}</pre><h3>Colors from this page</h3><div class="extracted-palette">${(meta.palette||[]).map(c=>`<span><i style="background:${esc(c.hex)}"></i>${esc(c.hex)}</span>`).join('')||'<p class="muted">No material colors detected.</p>'}</div>${suggestion.summary?`<h3>${esc(suggestion.style||'Page observations')}</h3><p>${esc(suggestion.summary)}</p><p class="muted">${esc(suggestion.evidence)}${suggestion.confidence?' · '+esc(suggestion.confidence)+' confidence':''}</p>`:''}</div></div>${p.images.length?`<h3>Images from page ${number}</h3><div class="extracted-images">${p.images.map(im=>`<figure>${img({...pageImage,image_number:im.number},'Extracted image '+im.number)}<figcaption>Image ${im.number} · ${im.kind==='composed_visual'?'Complete composition':im.kind==='independent_visual'?'Independent image':'Page crop'}${imageSlideCaption(id,number,im.number)}</figcaption></figure>`).join('')}</div>`:''}${(meta.warnings||[]).map(w=>`<p class="notice">${esc(w)}</p>`).join('')}`);
    $('.modal')?.classList.add('document-modal');hydrateImages();
}
document.addEventListener('keydown',e=>{
    if(!processingView.visible)return;
    if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();hideProcessing();}
    if(e.key==='Tab'){const controls=[...document.querySelectorAll('#processing-overlay button')];const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
},true);


let magnifiedPhoto=false;
function photoContentRect(im){const r=im.getBoundingClientRect(),ratio=im.naturalWidth/im.naturalHeight;if(!Number.isFinite(ratio)||ratio<=0)return r;const width=Math.min(r.width,r.height*ratio),height=width/ratio;return {left:r.left+(r.width-width)/2,top:r.top+(r.height-height)/2,width,height};}
function photoTransform(from,to){return `translate(${from.left+from.width/2-to.left-to.width/2}px,${from.top+from.height/2-to.top-to.height/2}px) scale(${from.width/to.width},${from.height/to.height})`;}
function openPhotoLightbox(){
    const def=slideDefs()[state.slide];if(!def?.visual)return;
    const source=document.querySelector('.photo-magnify img'),from=source?.complete&&source.naturalWidth?photoContentRect(source):null;
    magnifiedPhoto=true;renderPhotoLightbox();
    const im=$('#photo-lightbox img');if(from&&im&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const to=photoContentRect(im);if(to.width&&to.height)im.animate([{transform:photoTransform(from,to)},{transform:'none'}],{duration:240,easing:'cubic-bezier(.2,.75,.25,1)'});}
    $('#photo-lightbox [data-action="close-photo"]')?.focus();
}
function renderPhotoLightbox(){
    if(!magnifiedPhoto)return;const defs=slideDefs(),def=defs[state.slide];if(!def?.visual){closePhotoLightbox(false);return;}
    let root=$('#photo-lightbox');if(!root){root=document.createElement('div');root.id='photo-lightbox';root.className='photo-lightbox';root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','Full-screen image');document.body.append(root);}
    const original=showOriginalSlides.has(def.record?.id),f={...def.visual,show_original:original,slide_image_version:original?'':def.visual.slide_image_version};
    const key=def.id+'-'+imageKey(f)+'-'+comparingImage(def)+'-'+(slideImageJob(def.record?.id)?.status||'');
    if(root.dataset.photo!==key){
        const focusAction=root.contains(document.activeElement)?document.activeElement.dataset.action:'close-photo';
        root.innerHTML=`<header class="photo-lightbox-header"><div><strong>${esc(def.title)}</strong><span>${esc(slideTypeName(def))} · ${esc(situations[def.situation]||'Source image')}</span></div><button class="icon-button" data-action="close-photo" aria-label="Close full-screen image">${icon('close')}</button></header><div class="photo-lightbox-stage"><button class="icon-button photo-lightbox-prev" data-action="previous-photo-slide" aria-label="Previous slide" ${state.slide===0?'disabled':''}>${icon('left')}</button><figure>${visualImageArea(def,f,true)}</figure><button class="icon-button photo-lightbox-next" data-action="next-photo-slide" aria-label="Next slide" ${state.slide===defs.length-1?'disabled':''}>${icon('right')}</button></div><footer><span>${state.slide+1} / ${defs.length}</span><span>← → Navigate slides · Esc to close</span></footer>`;
        root.dataset.photo=key;root.querySelector(`[data-action="${focusAction||'close-photo'}"]`)?.focus();
    }
    $('#app').inert=true;$('#overlay').inert=true;document.body.classList.add('photo-lightbox-open');hydrateImages();
}
function closePhotoLightbox(animate=true){
    const root=$('#photo-lightbox');if(!root)return;magnifiedPhoto=false;
    const im=root.querySelector('img'),target=document.querySelector('.photo-magnify img');
    const finish=()=>{root.remove();$('#app').inert=false;$('#overlay').inert=false;document.body.classList.remove('photo-lightbox-open');document.querySelector('.photo-magnify')?.focus({preventScroll:true});};
    if(animate&&im&&target&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const from=photoContentRect(im),to=photoContentRect(target);root.style.pointerEvents='none';if(from.width&&to.width){im.animate([{transform:'none'},{transform:photoTransform(to,from)}],{duration:180,easing:'ease-in',fill:'forwards'}).finished.then(finish,finish);return;}}
    finish();
}
function navigatePhotoLightbox(direction){const defs=slideDefs(),next=state.slide+direction;if(next<0||next>=defs.length)return;if(defs[next].type==='photo'){moveSlide(direction);renderPhotoLightbox();}else{closePhotoLightbox(false);moveSlide(direction);}}
document.addEventListener('keydown',e=>{
    if(!magnifiedPhoto||e.target.closest('[data-comparison-range]'))return;
    if(['ArrowLeft','ArrowRight','Escape'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape')closePhotoLightbox();else navigatePhotoLightbox(e.key==='ArrowRight'?1:-1);return;}
    if(e.key==='Tab'){const controls=[...document.querySelectorAll('#photo-lightbox button:not(:disabled),#photo-lightbox input')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
},true);

start();

function applySession(session){state.user=session.user;state.csrf=session.csrf;state.studio=session.studio;state.studios=session.studios;state.studioTheme=cleanStudioTheme(session.studio_theme||{});}
async function resetStudio(){clearTimeout(state.poll);imageCache.forEach(url=>{if(url.startsWith('blob:'))URL.revokeObjectURL(url);});imageCache.clear();state.data=null;state.present=false;state.tab='projects';state.studioUsers=[];state.projects=(await api('projects')).projects;render();}
function studioUsersPage(){return `<div class="project-head"><div><h1>Studio users</h1><p class="muted">${esc(state.studio?.name)} · Admins can manage members. Project access comes from project teams.</p></div>${state.studio?.role==='admin'?button('Add user','edit-studio-user','primary','','plus'):''}</div><div class="member-list">${(state.studioUsers||[]).map(u=>`<article class="member-row"><span class="avatar">${esc(initials(u.name))}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div><span class="tag">${esc(u.role)}</span>${state.studio?.role==='admin'?`${button('Edit','edit-studio-user','small',`data-id="${esc(u.id)}"`)}${button('Remove','remove-studio-user','small danger-text',`data-id="${esc(u.id)}"`)}`:''}</article>`).join('')}</div>`;}
function studioUserModal(id){const u=(state.studioUsers||[]).find(u=>u.id===id)||{};openModal(u.id?'Edit studio member':'Add studio member',`<p>Members sign in with their own email. Existing accounts can belong to several studios.</p><form data-form="studio-user"><input type="hidden" name="id" value="${esc(u.id||'')}"><label>Name in this studio<input name="name" value="${esc(u.name||'')}" required maxlength="100"></label><label>Email<input type="email" name="email" value="${esc(u.email||'')}" ${u.id?'readonly':''} required></label><label>Role<select name="role"><option value="member" ${u.role!=='admin'?'selected':''}>Member</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin · can manage users</option></select></label>${formFooter(u.id?'Save member':'Add member')}</form>`);}
async function projectTeamModal(){const users=(await api('studio_users')).users,ids=new Set((state.data.members||[]).map(u=>u.id));openModal('Project team',`<p>Only these studio members can edit this project. Team-only projects are visible only to this list.</p><form data-form="project-team">${users.map(u=>`<label class="check-label"><input type="checkbox" name="user_ids" value="${esc(u.id)}" ${ids.has(u.id)?'checked':''}>${esc(u.name)} · ${esc(u.email)}</label>`).join('')}${formFooter('Save team')}</form>`);}
document.addEventListener('change',async e=>{if(e.target.id==='studio-select'){try{applySession(await api('switch_studio',{studio_id:e.target.value}));await resetStudio();}catch(error){toast(error.message);}}});

function projectSettingsModal(){const p=state.data.project;openModal('Project settings',`<form data-form="project-settings"><label>Visibility<select name="visibility"><option value="team" ${p.visibility!=='public'?'selected':''}>Team members only</option><option value="public" ${p.visibility==='public'?'selected':''}>Public · everyone in this studio can view</option></select></label><p class="form-hint">Only the project team can edit. Client presentations use separate sharing links.</p>${formFooter('Save settings')}</form><div class="modal-footer">${button('Manage project team','project-team','','','users')}${editable()?button('Presentation style','theme','','','edit'):''}</div>`);}
document.addEventListener('input',e=>{if(e.target.id==='project-search'){state.projectSearch=e.target.value;$('#project-grid').innerHTML=projectTiles();}});
document.addEventListener('change',async e=>{if(e.target.id==='show-archived'){state.showArchived=e.target.checked;try{await loadProjects();$('#project-grid').innerHTML=projectTiles();pollJobs();}catch(error){toast(error.message);}}});
